module clk_div (
    input wire clk,
    input wire rst,
    output wire dclk
);

    reg [17:0] q;

    always @(posedge clk or posedge rst) begin
        if (rst)
            q <= 18'b0;
        else
            q <= q + 1'b1;
    end

    assign dclk = q[1];

endmodule

module led_controller(
input wire clk,
input wire reset,
input wire [reg_width - 1:0] rf_data,
output wire [rf_addr_w - 1:0] rf_addr,
output wire [3:0] led
);
parameter [31:0] rf_addr_w=5;
parameter [31:0] reg_width=32;
parameter [1:0]
  read1 = 0,
  read2 = 1,
  read3 = 2,
  idle = 3;
reg [1:0] state; reg [1:0] state_next;
reg [31:0] delay; reg [31:0] delay_next;
reg [rf_addr_w - 1:0] addr; reg [rf_addr_w - 1:0] addr_next;
reg [reg_width - 1:0] sum; reg [reg_width - 1:0] sum_next;
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      state <= idle;
      delay <= 0;
      addr <= {((rf_addr_w - 1)-(0)+1){1'b0}};
      sum <= {((reg_width - 1)-(0)+1){1'b0}};
    end
    else begin
      state <= state_next;
      delay <= delay_next;
      addr <= addr_next;
      sum <= sum_next;
    end
  end
  //reg 5 & 17 or 0
  always @(state, delay, rf_data, addr, sum) begin
    state_next <= state;
    delay_next <= delay;
    addr_next <= addr;
    sum_next <= sum;
    case(state)
    read1 : begin
      sum_next <= rf_data;
      addr_next <= 5'b10001;
      state_next <= read2;
    end
    read2 : begin
      sum_next <= sum & rf_data;
      addr_next <= 5'b00000;
      state_next <= read3;
    end
    read3 : begin
      sum_next <= sum | rf_data;
      state_next <= idle;
    end
    idle : begin
      if(delay == 100) begin
        delay_next <= 0;
        state_next <= read1;
        addr_next <= 5'b00101;
      end
      else begin
        delay_next <= delay + 1;
      end
    end
    endcase
  end
  assign led = sum[3:0];
  assign rf_addr = addr;
endmodule

