module uart_receive(
input wire rst_i,
input wire clk_i,
input wire Top16_i,
input wire TopRx_i,
output reg [7:0] Dout_o,
output wire ClrDiv_o,
output reg Recvd,
input wire Rx_i
);
parameter [2:0]
  idle = 0,
  start_rx = 1,
  edge_rx = 2,
  shift_rx = 3,
  stop_rx = 4,
  rxovf = 5;
  //constant NDbits : std_logic_vector(2 downto 0) :=8;
reg [2:0] RxFSM;
reg [7:0] Rx_Reg;
reg [31:0] RxBitCnt;
wire RxRdyi;
wire ClrDiv;
wire RxErr;
  // ------------------------
  // RECEIVE State Machine
  // ------------------------
  always @(posedge rst_i, posedge clk_i) begin
    if(rst_i == 1'b1) begin
      Rx_Reg <= {8{1'b0}};
      Dout_o <= {8{1'b0}};
      RxBitCnt <= 0;
      Recvd <= 1'b0;
      RxFSM <= Idle;
    end else begin
      case(RxFSM)
      Idle : begin
        Recvd <= 1'b0;
        if(Top16_i == 1'b1 && Rx_i == 1'b0) begin
          RxFSM <= Start_Rx;
          RxBitCnt <= 0;
        end
      end
      Start_Rx : begin
        if(TopRx_i == 1'b1) begin
          if(Rx_i == 1'b1) begin
            RxFSM <= RxOVF;
          end
          else begin
            RxFSM <= Edge_Rx;
          end
        end
      end
      Edge_Rx : begin
        if(TopRx_i == 1'b1) begin
          if(RxBitCnt == 8) begin
            RxFSM <= Stop_Rx;
          end
          else begin
            RxFSM <= Shift_Rx;
          end
        end
      end
      Shift_Rx : begin
        if(TopRx_i == 1'b1) begin
          RxFSM <= Edge_Rx;
          Rx_Reg[RxBitCnt] <= Rx_i;
          RxBitCnt <= RxBitCnt + 1;
        end
      end
      Stop_Rx : begin
        if(TopRx_i == 1'b1) begin
          RxFSM <= Idle;
          Dout_o <= Rx_Reg;
          Recvd <= 1'b1;
        end
      end
      RxOVF : begin
        if(Rx_i == 1'b1) begin
          RxFSM <= Idle;
        end
      end
      endcase
    end
  end
  assign ClrDiv_o = ClrDiv;
  assign RxRdyi = RxFSM == Idle ? 1'b1 : 1'b0;
  assign RxErr = RxFSM == RxOVF ? 1'b1 : 1'b0;
  assign ClrDiv = RxFSM == idle && Top16_i == 1'b1 && Rx_i == 1'b0 ? 1'b1 : 1'b0;
endmodule

module exceptions(
input wire [31:0] in1,
input wire [31:0] in2,
input wire [31:0] int_mul,
input wire enable,
input wire m_in47,
output reg [31:0] exp_out
);
wire [8:0] expa;
wire [8:0] expb;
wire [8:0] summ;
wire [8:0] m;
  assign expa = {1'b0,in1[30:23]};
  assign expb = {1'b0,in2[30:23]};
  assign m = {8'b00000000,m_in47};
  assign summ = (expa) + (expb) + (m);
  always @(enable, in1, in2, int_mul, summ) begin
    if((enable == 1'b1)) begin
      // not anumber 
      if((in1[30:23] == 8'b11111111 && in1[22:0] != 23'b00000000000000000000000)) begin
        exp_out <= 32'b11111111111111111111111111111111;
        // NaN
      end
      else if((in2[30:23] == 8'b11111111 && in2[22:0] != 23'b00000000000000000000000)) begin
        exp_out <= 32'b11111111111111111111111111111111;
        // NaN
      end
      else if((in1 == 32'h00000000)) begin
        // zero by infinity or negative infinity  = NaN
        if((in2[30:0] == 31'b1111111100000000000000000000000)) begin
          exp_out <= 32'b11111111111111111111111111111111;
          //NaN
          // zero by any number = 0 
        end
        else begin
          exp_out <= {32{1'b0}};
        end
      end
      else if((in2 == 32'h00000000)) begin
        if((in1[30:0] == 31'b1111111100000000000000000000000)) begin
          exp_out <= 32'b11111111111111111111111111111111;
          // NaN
        end
        else begin
          exp_out <= {32{1'b0}};
        end
      end
      else if((in1[30:0] == 31'b1111111100000000000000000000000)) begin
        exp_out <= {int_mul[31],in1[30:0]};
      end
      else if((in2[30:0] == 31'b1111111100000000000000000000000)) begin
        exp_out <= {int_mul[31],in2[30:0]};
        //-overflow detector \\\ ----
      end
      else if((summ >= 9'b111111100)) begin
        exp_out <= {int_mul[31],31'b1111111100000000000000000000000};
        // underflow detector
      end
      else if((summ <= 9'b001111111)) begin
        exp_out <= 32'b00000000000000000000000000000000;
      end
      else begin
        exp_out <= int_mul;
      end
    end
  end
endmodule

module sourceout_ctrl_2bit(
    input clk,
    input nRST,
    input [31:0] data_length,
    input [31:0] blank_length,
    input [14:0] fifo_usedw,
    output reg data_en
);

    localparam IDLE = 3'b000;
    localparam WAIT_SEND = 3'b001;
    localparam START_SEND = 3'b010;
    localparam SEND_POS = 3'b011;
    localparam SEND_NEG = 3'b100;

    reg [2:0] state;
    reg [31:0] pos_num, neg_num, count;
    reg [14:0] fifo_usedw_reg;

    always @(posedge clk or negedge nRST) begin
        if (!nRST) begin
            state <= IDLE;
            data_en <= 1'b0;
            count <= 32'b0;
        end
        else begin
            case (state)
                IDLE: begin
                    data_en <= 1'b0;
                    if (fifo_usedw >= 15'h1388) begin // 5000 entries
                        state <= WAIT_SEND;
                    end
                end
                WAIT_SEND: begin
                    if (fifo_usedw >= 15'h1388) begin
                        state <= START_SEND;
                    end
                end
                START_SEND: begin
                    count <= 32'b0;
                    state <= SEND_POS;
                end
                SEND_POS: begin
                    data_en <= 1'b1;
                    count <= count + 1;
                    if (count == pos_num) begin
                        if (neg_num != 0) begin
                            state <= SEND_NEG;
                        end
                        else begin
                            state <= SEND_POS;
                        end
                    end
                end
                SEND_NEG: begin
                    data_en <= 1'b0;
                    count <= count + 1;
                    if (count == neg_num) begin
                        state <= SEND_POS;
                    end
                end
            endcase

            if (fifo_usedw < 15'h1388) begin
                state <= IDLE;
            end

            fifo_usedw_reg <= fifo_usedw;
            pos_num <= (data_length * 32'd2) / 32'd1;
            neg_num <= (blank_length * 32'd2) / 32'd1;
        end
    end

endmodule

module EXT_FIFO_WR_CTRL (
    input        CLK,
    input        RESET,
    input        RD_RST_N,
    input        MASTER_SINK_DAV,
    input        MASTER_SINK_VAL,
    input        MASTER_SINK_SOP,
    input        MASTER_SINK_EOP,
    input        MASTER_SINK_ERR,
    input  [3:0] MASTER_SINK_MTY,
    input [31:0] MASTER_SINK_DAT,
    input        FIFOA_AF_N,
    input        FIFOA_FF_N,
    output       WR_RST_N,
    output       MASTER_SINK_ENA,
    output       FIFOA_RST_N,
    output       FIFOA_CS_N,
    output       FIFOA_EN,
    output       FIFOA_WR,
    output [31:0] FIFOA_DATA
);

    reg        wr_rst_n;
    reg        master_sink_ena;
    reg        fifoa_rst_n;
    reg        fifoa_cs_n;
    reg        fifoa_en;
    reg        fifoa_wr;
    reg [31:0] fifoa_data;

    always @(posedge CLK or negedge RESET) begin
        if (!RESET) begin
            wr_rst_n <= 1'b0;
            master_sink_ena <= 1'b0;
            fifoa_rst_n <= 1'b0;
            fifoa_cs_n <= 1'b1;
            fifoa_en <= 1'b0;
            fifoa_wr <= 1'b0;
            fifoa_data <= 32'b0;
        end
        else begin
            wr_rst_n <= RD_RST_N;
            fifoa_rst_n <= RD_RST_N;

            if (MASTER_SINK_DAV && MASTER_SINK_VAL) begin
                if (!FIFOA_FF_N && !FIFOA_AF_N) begin
                    master_sink_ena <= 1'b1;
                    fifoa_cs_n <= 1'b0;
                    fifoa_en <= 1'b1;
                    fifoa_wr <= 1'b1;
                    fifoa_data <= MASTER_SINK_DAT;
                end
                else begin
                    master_sink_ena <= 1'b0;
                    fifoa_cs_n <= 1'b1;
                    fifoa_en <= 1'b0;
                    fifoa_wr <= 1'b0;
                end
            end
            else begin
                master_sink_ena <= 1'b0;
                fifoa_cs_n <= 1'b1;
                fifoa_en <= 1'b0;
                fifoa_wr <= 1'b0;
            end
        end
    end

    assign WR_RST_N = wr_rst_n;
    assign MASTER_SINK_ENA = master_sink_ena;
    assign FIFOA_RST_N = fifoa_rst_n;
    assign FIFOA_CS_N = fifoa_cs_n;
    assign FIFOA_EN = fifoa_en;
    assign FIFOA_WR = fifoa_wr;
    assign FIFOA_DATA = fifoa_data;

endmodule

module clock_divider (
    input wire clk,
    input wire rst,
    output reg clk_div
);

    parameter constantNumber = 8000;

    reg [63:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 64'd0;
            clk_div <= 1'b0;
        end else if (count == constantNumber - 1) begin
            count <= 64'd0;
            clk_div <= ~clk_div;
        end else begin
            count <= count + 1'b1;
        end
    end

endmodule

module traffic_light_controller (
    input wire clk,
    input wire reset,
    output reg [5:0] count,
    output reg [1:0] state
);

// State definitions
localparam S0 = 2'b00;
localparam S1_GREEN = 2'b01;
localparam S2_YELLOW = 2'b10;
localparam S3_RED = 2'b11;

// Combinatorial logic for state transitions
always @(*) begin
    case (count)
        6'd0: state = S1_GREEN;
        6'd25: state = S2_YELLOW;
        6'd28: state = S3_RED;
        6'd41: state = S1_GREEN;
        default: state = state; // Maintain current state
    endcase
end

// Sequential logic for counter and reset
always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 6'd0;
        state <= S0;
    end else begin
        if (count == 6'd41) begin
            count <= 6'd0;
        end else begin
            count <= count + 1'b1;
        end
    end
end

endmodule

module sequence_change_detector (
    input wire clk,
    input wire rst_n,
    input wire [3:0] sequence_in,
    output reg [3:0] sequence_out
);

reg [3:0] prev_sequence;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        prev_sequence <= 4'b0000;
        sequence_out <= 4'b0000;
    end else begin
        if (sequence_in != prev_sequence) begin
            sequence_out <= prev_sequence;
        end
        prev_sequence <= sequence_in;
    end
end

endmodule

module bin_to_bcd_4bit(
    input [3:0] bin,
    output [7:0] bcd
);

    wire nb3, nb2, nb1;

    assign nb3 = ~bin[3];
    assign nb2 = ~bin[2];
    assign nb1 = ~bin[1];

    assign bcd[7:5] = 3'b000;

    assign bcd[4] = bin[3] & (bin[2] | bin[1]);
    assign bcd[3] = (nb3 & bin[2]) | (bin[3] & nb2 & bin[1]);
    assign bcd[2] = (nb3 & nb2 & bin[1]) | (nb3 & bin[2] & nb1) | (bin[3] & nb2 & nb1);
    assign bcd[1] = (nb3 & nb2 & bin[1]) | (nb3 & bin[2] & nb1) | (bin[3] & nb2 & bin[1]) | (bin[3] & bin[2] & nb1);
    assign bcd[0] = bin[0];

endmodule

module ALU_Ctrl (
    input [5:0] funct_i,
    input [2:0] ALUOp_i,
    output reg [3:0] ALU_operation_o,
    output reg [1:0] FURslt_o
);

always @(*) begin
    if (ALUOp_i == 3'b001) begin
        ALU_operation_o = 4'b0010;
        FURslt_o = 2'b00;
    end
    else begin
        case ({ALUOp_i, funct_i})
            9'b000_100000: begin // add
                ALU_operation_o = 4'b0010;
                FURslt_o = 2'b00;
            end
            9'b000_100010: begin // sub
                ALU_operation_o = 4'b0110;
                FURslt_o = 2'b00;
            end
            9'b000_100100: begin // and
                ALU_operation_o = 4'b0000;
                FURslt_o = 2'b00;
            end
            9'b000_100101: begin // or
                ALU_operation_o = 4'b0001;
                FURslt_o = 2'b00;
            end
            9'b000_101010: begin // slt
                ALU_operation_o = 4'b0111;
                FURslt_o = 2'b00;
            end
            9'b101_000000: begin // sll
                ALU_operation_o = 4'b1000;
                FURslt_o = 2'b10;
            end
            9'b101_000011: begin // sra
                ALU_operation_o = 4'b1011;
                FURslt_o = 2'b10;
            end
            default: begin
                ALU_operation_o = 4'b1111;
                FURslt_o = 2'b11;
            end
        endcase
    end
end

endmodule

module sign_extend (
    input [31:0] data_in,
    output reg [31:0] data_out
);

always @(*) begin
    case (data_in[31:28])
        4'b1111: data_out = {{20{data_in[21]}}, data_in[21:10]};
        4'b0101: data_out = {{26{data_in[15]}}, data_in[15:10]};
        default: data_out = 32'b0;
    endcase
end

endmodule

module RF(
input wire [4:0] rs1,
input wire [4:0] rs2,
input wire [4:0] rd,
input wire [31:0] DWR,
input wire rst,
output reg [31:0] Crs1,
output reg [31:0] Crs2
);
reg [31:0] RAM[31:0] = 32'b00000000000000000000000000000000;  //registro g0 siempre es cero
  always @(rs1, rs2, rd, DWR, rst, RAM) begin
    if(rst == 1'b0) begin
      if(rd > 5'b00000) begin
        RAM[rd] <= DWR;
