      Crs1 <= RAM[rs1];
      Crs2 <= RAM[rs2];
    end
    else begin
      RAM <= {32{32'b00000000000000000000000000000000}};
      Crs1 <= {32{1'b0}};
      Crs2 <= {32{1'b0}};
    end
