module STD_04000_good(
input wire i_Clock,
input wire i_Reset_n,
input wire i_Start,
input wire i_Stop
);
// Clock input
// Reset input
// Start counter signal
// Stop counter signal
//CODE
parameter c_Length = 1'b1;  // How long we should count
parameter [1:0]
  init = 0,
  loading = 1,
  enabled = 2,
  finished = 3;
  // Enumerated type for state encoding
reg [1:0] sm_State;  // State signal
reg Raz;  // Load the length value and initialize the counter
reg Enable;  // Counter enable signal
reg [3:0] Count_Length;  // Counter length for counting
wire End_Count;  // End signal of counter
  // A simple counter with loading length and enable signal
  Counter Counter(
      .i_Clock(i_Clock),
    .i_Reset_n(i_Reset_n),
    .i_Raz(Raz),
    .i_Enable(Enable),
    .i_Length(Count_Length),
    .o_Done(End_Count));
  // FSM process controlling the counter. Start or stop it in function of the input (i_Start & i_Stop),
  // load the length value, and wait for it to finish
  always @(posedge i_Reset_n, posedge i_Clock) begin
    if((i_Reset_n == 1'b0)) begin
      sm_State <= init;
      Raz <= 1'b0;
      Enable <= 1'b0;
      Count_Length <= {4{1'b0}};
    end else begin
      case(sm_State)
      init : begin
        // Set the length value
        Count_Length <= c_Length;
        sm_State <= loading;
      end
      loading : begin
        // Load the counter and initialize it
        Raz <= 1'b1;
        sm_State <= enabled;
      end
      enabled : begin
        // Start or stop counting depending on inputs until it finishes
        Raz <= 1'b0;
        if((End_Count == 1'b0)) begin
          // The counter has not finished, wait
          Enable <= i_Start ^  ~i_Stop;
          sm_State <= Enabled;
        end
        else begin
          // The counter has finished, nothing else to do
          Enable <= 1'b0;
          sm_State <= finished;
        end
      end
      default : begin
        sm_State <= init;
      end
      endcase
    end
  end
//CODE
endmodule

module icap (
    input wire c,
    input wire w,
    input wire [31:0] i,
    output wire [31:0] O
);

    wire [31:0] swapped;

    genvar j;
    generate
        for (j = 0; j < 4; j = j + 1) begin : swap_block
            assign swapped[j*8+:8] = {i[j*8+7], i[j*8+6], i[j*8+5], i[j*8+4],
                                      i[j*8+3], i[j*8+2], i[j*8+1], i[j*8]};
        end
    endgenerate

    (* BOX_TYPE = "BLACK_BOX" *)
    ICAPE2 #(
        .ICAP_WIDTH("X32")
    ) icape2_inst (
        .CLK(c),
        .CSIB(~w),
        .I(swapped),
        .O(O),
        .RDWRB(1'b0)
    );

endmodule

module digital_delay (
    input wire Enable,
    input wire Clk,
    input wire Reset,
    input wire CE_N,
    input wire OE_N,
    input wire WE_N,
    input wire UB_N,
    input wire LB_N,
    input wire [7:0] Time,
    input wire [7:0] Repeats,
    input wire [7:0] Mix,
    input wire [19:0] SRAM_ADDR,
    input wire [23:0] D_In,
    inout wire [15:0] SRAM_DQ,
    output reg [23:0] D_Out
);

    // Internal registers
    reg [19:0] write_addr;
    reg [19:0] read_addr;
    reg [7:0] repeat_count;
    reg [23:0] delayed_sample;
    reg [23:0] mixed_output;

    // SRAM control
    reg sram_we_n;
    reg [15:0] sram_data_out;
    wire [15:0] sram_data_in;

    assign SRAM_DQ = (!OE_N && WE_N) ? sram_data_out : 16'bz;
    assign sram_data_in = SRAM_DQ;

    always @(posedge Clk or posedge Reset) begin
        if (Reset) begin
            write_addr <= 20'b0;
            read_addr <= 20'b0;
            repeat_count <= 8'b0;
            D_Out <= 24'b0;
        end else if (Enable) begin
            // Write input sample to SRAM
            sram_we_n <= 1'b0;
            sram_data_out <= D_In[23:8];  // Write upper 16 bits
            write_addr <= (write_addr + 1) % (2**20);  // Circular buffer

            // Read delayed sample from SRAM
            sram_we_n <= 1'b1;
            read_addr <= (write_addr - Time) % (2**20);
            delayed_sample <= {sram_data_in, 8'b0};  // Pad with zeros for lower 8 bits

            // Mix original and delayed samples
            mixed_output <= (D_In * (8'd255 - Mix) + delayed_sample * Mix) / 8'd255;

            // Update output and repeat count
            if (repeat_count < Repeats) begin
                D_Out <= mixed_output;
                repeat_count <= repeat_count + 1;
            end else begin
                D_Out <= D_In;
                repeat_count <= 8'b0;
            end
        end
    end

    // SRAM control signals
    assign CE_N = !Enable;
    assign OE_N = sram_we_n;
    assign WE_N = sram_we_n;
    assign UB_N = 1'b0;
    assign LB_N = 1'b0;

endmodule

module compuertas(
input wire A,
input wire B,
output wire [8:0] y
);
  assign y[0] =  ~(A);
  //declaramos que la primera posicion del arreglo realizara una negacion a la entrada A
  assign y[1] =  ~(B);
  //en la posicion 1 del arreglo negamos la entrada B
  assign y[2] = A & B;
  //en la posicion 2 del arreglo hacemos un A and B ó A y B
  assign y[3] =  ~(A & B);
  //en la posicion 3 del arreglo hacemos un A nand B lo que hara lo mismo que and pero negando el result
  assign y[4] = A | B;
  //la posicion 4 del arreglo se realizara la operacion or
  assign y[5] =  ~(A | B);
  //la posicion 5 returnara el valor dado por la compuerta nor (or negado)
  assign y[6] = A ^ B;
  //la posicion 6 muestra el valor de un xor entre A y B (A xor B)
  assign y[7] =  ~(A ^ B);
  assign Y[8] =  ~( ~(a & (b | a)));
    //para que la posicion 7 reciviera el xnor, no se puede realizar de los medios 
  //anteriores porque no existe en el programa pero se resuelve simplemente aplicando un xor
  //y negando el resultado
endmodule

module RAM(
    input Enable,
    input ReadWrite,
    input Clock,
    input [15:0] DataIn,
    input [255:0] Result,
    input [255:0] C,
    input [255:0] AT,
    input [255:0] BB,
    input [255:0] FinResult,
    output reg [15:0] DataOut
);

    reg [15:0] MemArray [0:255];

    always @(posedge Clock) begin
        if (Enable) begin
            if (ReadWrite) begin
                if (Result[0]) DataOut <= MemArray[0];
                else if (C[0]) DataOut <= MemArray[1];
                else if (AT[0]) DataOut <= MemArray[2];
                else if (BB[0]) DataOut <= MemArray[3];
                else if (FinResult[0]) DataOut <= MemArray[4];
            end else begin
                if (Result[0]) MemArray[0] <= DataIn;
                else if (C[0]) MemArray[1] <= DataIn;
                else if (AT[0]) MemArray[2] <= DataIn;
                else if (BB[0]) MemArray[3] <= DataIn;
                else if (FinResult[0]) MemArray[4] <= DataIn;
            end
        end else begin
            DataOut <= 16'bZ;
        end
    end

endmodule

module PHASE (
    input wire clk,
