);

always @(posedge clk or posedge reset) begin
    if (reset) begin
        phaseOut <= 1'b0;
    end else begin
        phaseOut <= ~phaseOut;
    end
end

endmodule

module BaudRateGen #(
    parameter BAUD_RATE = 9600
)(
    input clk,
    input reset,
    output reg Baud8Tick
);

    localparam CLKS_PER_BIT = 50000000 / BAUD_RATE / 8;
    reg [15:0] counter;

    always @(posedge clk or negedge reset) begin
        if (~reset) begin
            counter <= 0;
            Baud8Tick <= 0;
        end
        else begin
            if (counter == CLKS_PER_BIT - 1) begin
                Baud8Tick <= 1;
                counter <= 0;
            end
            else begin
                Baud8Tick <= 0;
                counter <= counter + 1;
            end
        end
    end

endmodule

module RealBackground (
    input wire Clk,
    input wire reset,
    input wire [22:0] read_address,
    inout wire [7:0] data_out,
    output reg [22:0] out_add,
    output reg [3:0] out1,
    output reg [3:0] out2,
    output reg sel
);

    // State definition
    localparam R1 = 1'b0;
    localparam R2 = 1'b1;

    reg state, next_state;
    reg [3:0] reg1;
    reg [22:0] add;

    // State transition logic
    always @(posedge Clk or posedge reset) begin
        if (reset)
            state <= R1;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        next_state = ~state;
    end

    // Output and register update logic
    always @(posedge Clk) begin
        case (state)
            R1: begin
                out_add <= read_address;
                out1 <= reg1;
                out2 <= 4'b0000;
                sel <= 1'b0;
                add <= read_address;
            end
            R2: begin
                reg1 <= data_out[7:4];
                out2 <= data_out[3:0];
                out1 <= 4'b0000;
                out_add <= add;
                sel <= 1'b1;
            end
        endcase
    end

endmodule

module alu_8bit(
    input [7:0] a,
    input [7:0] b,
    input cin,
    input [2:0] select,
    output reg [7:0] out,
    output reg carry,
    output zero
);

    reg [8:0] result;

    always @(*) begin
        #1;
        case(select)
            3'b000: result = a + b + cin;  // ADD
            3'b001: result = a - b - 1 + cin;  // SUB
            3'b010: result = b - a - 1 + cin;  // SUB1
            3'b011: begin  // AND_OP
                result[7:0] = a & b;
                result[8] = 1'b0;
            end
            3'b100: begin  // OR_OP
                result[7:0] = a | b;
                result[8] = 1'b0;
            end
            3'b101: begin  // XOR_OP
                result[7:0] = a ^ b;
                result[8] = 1'b0;
            end
            3'b110: begin  // XOR1_OP
                result[7:0] = a ^~ b;
                result[8] = 1'b0;
            end
            default: result = 9'b0;
        endcase

        out = result[7:0];
        carry = result[8];
    end

    assign zero = (out == 8'b0);

endmodule

module fab(
    input clk, reset, s,
    input [7:0] in,
    input [1:0] op,
    output reg [7:0] out,
    output reg done
);

    parameter Wait = 3'b000, INIT1 = 3'b001, INIT2 = 3'b010,
              FIB1 = 3'b011, FIB2 = 3'b100, FIB3 = 3'b101, FIB4 = 3'b110,
              FACT1 = 3'b111, FACT2 = 3'b000, FACT3 = 3'b001, Pond = 3'b010;

    reg [7:0] A, B, C, sum;
    reg [2:0] present_state, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            present_state <= Wait;
            done <= 0;
        end else begin
            present_state <= next_state;
        end
    end

    always @(*) begin
        case (present_state)
            Wait: next_state = s ? (op == 2'b00 ? INIT1 : (op == 2'b01 ? FIB1 : FACT1)) : Wait;
            INIT1: next_state = INIT2;
            INIT2: next_state = Pond;
            FIB1: next_state = FIB2;
            FIB2: next_state = (C == 0) ? Pond : FIB3;
            FIB3: next_state = FIB4;
            FIB4: next_state = FIB2;
            FACT1: next_state = (C == 1) ? Pond : FACT2;
            FACT2: next_state = FACT3;
            FACT3: next_state = FACT1;
            Pond: next_state = s ? Pond : Wait;
            default: next_state = Wait;
        endcase
    end

    always @(posedge clk) begin
        case (present_state)
            Wait: begin
                A <= 0;
                B <= 1;
                C <= in;
                done <= 0;
            end
            INIT1: begin
                out <= B;
                done <= 1;
            end
            FIB1: begin
                sum <= A + B;
                C <= C - 1;
            end
            FIB3: begin
                A <= B;
                B <= sum;
            end
            FIB4: begin
                sum <= A + B;
                C <= C - 1;
            end
            FACT1: begin
                if (C == 1) begin
                    out <= B;
                    done <= 1;
                end
            end
            FACT2: begin
                B <= B * C;
            end
            FACT3: begin
                C <= C - 1;
            end
        endcase
    end

endmodule

module ClockPrescaler(
output wire clk_25MHZ,
output wire clk_25HZ,
output wire [31:0] GPIO_0,
input wire RST_N,
input wire MCLK
);
//------SYSTEMS signals
reg clk;
reg clkBall;
  always @(posedge MCLK, posedge RST_N) begin : P1
    reg [31:0] timeCount;
    reg [31:0] timeCountBall;
    if(RST_N == 1'b0) begin
      timeCount = 0;
      timeCountBall = 0;
      clk <= 1'b0;
      clkBall <= 1'b0;
    end else begin
      timeCount = timeCount + 1;
      timeCountBall = timeCountBall + 1;
      if(timeCount == 1) begin
        clk <=  ~clk;
        timeCount = 0;
      end
      if(timeCountBall == 1999999) begin
        clkBall <= 1'b1;
        timeCountBall = 0;
      end
      else begin
        clkBall <= 1'b0;
      end
    end
  end
  assign clk_25MHZ = clk;
  assign clk_25HZ = clkBall;
endmodule

module udp_add_udp_header(
input wire clk,
input wire data_valid_in,
input wire [7:0] data_in,
output reg data_valid_out,
output reg [7:0] data_out,
input wire [31:0] ip_src_ip,
input wire [31:0] ip_dst_ip,
input wire [15:0] udp_src_port,
input wire [15:0] udp_dst_port,
input wire [15:0] data_length,
input wire [15:0] data_checksum
);
reg [8:0] data_delay[0:8] = 1'b0;  //--------------------------------------------------------------
// Note: Set the initial state to pass the data striaght through
//--------------------------------------------------------------
reg [3:0] count = 1'b1;
reg data_valid_in_last = 1'b0;
wire [15:0] udp_length;
reg [19:0] udp_checksum_u1a;
reg [19:0] udp_checksum_u1b;
reg [16:0] udp_checksum_u2;
reg [15:0] udp_checksum_u3;
reg [15:0] udp_checksum;  //------------------------------------------------------------------
// UDP checksum is calculated based on a pseudo header that includes
// the source and destination IP addresses
//------------------------------------------------------------------
wire [15:0] pseudohdr_0 = 1'b0;
wire [15:0] pseudohdr_1 = 1'b0;
wire [15:0] pseudohdr_2 = 1'b0;
wire [15:0] pseudohdr_3 = 1'b0;
wire [15:0] pseudohdr_4 = 1'b0;
wire [15:0] pseudohdr_5 = 1'b0;
wire [15:0] pseudohdr_6 = 1'b0;
wire [15:0] pseudohdr_7 = 1'b0;
wire [15:0] pseudohdr_8 = 1'b0;
wire [15:0] pseudohdr_9 = 1'b0;
  assign udp_length = (data_length) + 8;
  assign pseudohdr_0 = {ip_src_ip[7:0],ip_src_ip[15:8]};
  assign pseudohdr_1 = {ip_src_ip[23:16],ip_src_ip[31:24]};
  assign pseudohdr_2 = {ip_dst_ip[7:0],ip_dst_ip[15:8]};
  assign pseudohdr_3 = {ip_dst_ip[23:16],ip_dst_ip[31:24]};
  assign pseudohdr_4 = 16'h0011;
  // UDP Protocol
  assign pseudohdr_5 = udp_length;
  assign pseudohdr_6 = udp_src_port;
  assign pseudohdr_7 = udp_dst_port;
  assign pseudohdr_8 = udp_length;
  assign pseudohdr_9 = udp_checksum;
  always @(posedge clk) begin
    case(count)
    4'b0000 : begin
      data_out <= udp_src_port[15:8];
      data_valid_out <= 1'b1;
    end
    4'b0001 : begin
      data_out <= udp_src_port[7:0];
      data_valid_out <= 1'b1;
    end
    4'b0010 : begin
      data_out <= udp_dst_port[15:8];
      data_valid_out <= 1'b1;
    end
    4'b0011 : begin
      data_out <= udp_dst_port[7:0];
      data_valid_out <= 1'b1;
    end
    4'b0100 : begin
      data_out <= udp_length[15:8];
      data_valid_out <= 1'b1;
    end
    4'b0101 : begin
      data_out <= udp_length[7:0];
      data_valid_out <= 1'b1;
    end
    4'b0110 : begin
      data_out <= udp_checksum[15:8];
      data_valid_out <= 1'b1;
    end
    4'b0111 : begin
      data_out <= udp_checksum[7:0];
      data_valid_out <= 1'b1;
    end
    default : begin
      data_out <= data_delay[0][7:0];
      data_valid_out <= data_delay[0][8];
    end
    endcase
    data_delay[0:(8) - 1] <= data_delay[1:(8)];
    if(data_valid_in == 1'b1) begin
      data_delay[(8)] <= {1'b1,data_in};
      if(data_valid_in_last == 1'b0) begin
        count <= {4{1'b0}};
      end
      else if(count != 4'b1111) begin
        count <= count + 1;
      end
    end
    else begin
      data_delay[(8)] <= {1{1'b0}};
      if(count != 4'b1111) begin
        count <= count + 1;
      end
    end
    data_valid_in_last <= data_valid_in;
    // Pipelined checksum calculation    
    udp_checksum_u1a <= (0) + (pseudohdr_0) + (pseudohdr_1) + (pseudohdr_2) + (pseudohdr_3) + (pseudohdr_4);
    udp_checksum_u1b <= (0) + (pseudohdr_5) + (pseudohdr_6) + (pseudohdr_7) + (pseudohdr_8) + (data_checksum);
    udp_checksum_u2 <= (0) + udp_checksum_u1a[15:0] + udp_checksum_u1a[19:16] + udp_checksum_u1b[15:0] + udp_checksum_u1b[19:16];
    udp_checksum_u3 <= udp_checksum_u2[15:0] + udp_checksum_u2[16:16];
    udp_checksum <=  ~(udp_checksum_u3);
  end
endmodule

