  always @(posedge CLR, posedge CLK) begin
    if((CLR == 1'b1)) begin
      outS <= {((N - 1)-(0)+1){1'b0}};
    end else begin
      if((CE == 1'b1)) begin
        outS[0] <= Din;
        for (i=1; i <= N - 1; i = i + 1) begin
          outS[i] <= outS[i - 1];
        end
      end
    end
  end
  assign Dout = outS;
endmodule

