module fifo_out_cal_addr (
    input [2:0] state,
    input [4:0] head,
    input [4:0] tail,
    input [5:0] data_count,
    output reg we,
    output reg re,
    output reg [4:0] next_head,
    output reg [4:0] next_tail,
    output reg [5:0] next_data_count
);

always @(*) begin
    case (state)
        3'b000: begin // IDLE
            we = 1'b0;
            re = 1'b0;
            next_head = head;
            next_tail = tail;
            next_data_count = data_count;
        end
        3'b001: begin // WRITE
            we = 1'b1;
            re = 1'b0;
            next_head = head;
            next_tail = tail + 1'b1;
            next_data_count = data_count + 1'b1;
        end
        3'b010: begin // READ
            we = 1'b0;
            re = 1'b1;
            next_head = head + 1'b1;
            next_tail = tail;
            next_data_count = data_count - 1'b1;
        end
        3'b011: begin // WR_ERROR
            we = 1'b0;
            re = 1'b0;
            next_head = head;
            next_tail = tail;
            next_data_count = data_count;
        end
        3'b100: begin // RD_ERROR
            we = 1'b0;
            re = 1'b0;
            next_head = head;
            next_tail = tail;
            next_data_count = data_count;
        end
        default: begin
            we = 1'bx;
            re = 1'bx;
            next_head = 5'bxxxxx;
            next_tail = 5'bxxxxx;
            next_data_count = 6'bxxxxxx;
        end
    endcase
end

endmodule

