module parameterized_and_gate(
input wire [bits - 1:0] A,
output wire O
);
parameter [31:0] bits=0;
//inputs
//outputs
//--------------------------------------------------------
//              Parameterized OR gate                   --
//--------------------------------------------------------
//SIGNALS
wire [2 * ceil2[bits] - 2:0] im = 1'b0;
  //connect inputs
  genvar j;
  generate for (j=0; j <= bits - 1; j = j + 1) begin: connect_input
      assign im[j] = A[j];
  end
  endgenerate
  //inputs
  generate if ((ceil2[bits] != bits)) begin: blank_inputs
      genvar k;
    generate for (k=bits; k <= ceil2[bits] - 1; k = k + 1) begin: connect_low
          assign im[k] = 1'b1;
    end
    endgenerate
        //connect low state
  end
  endgenerate
  //zeros on input
  //generate tree of gates
  genvar g;
  generate for (g=0; g <= ceil2[bits] - 2; g = g + 1) begin: or_gates
      assign im[g + ceil2[bits]] = im[g * 2] & im[g * 2 + 1];
  end
  endgenerate
  //g
  //connect output
  assign O = im[(2 * ceil2[bits] - 2)];
// end of architecture
endmodule

