module TFT_CTRL_800_480_16bit (
    input  Clk33M,
    input  Rst_n,
    input  [15:0] data_in,
    output [11:0] hcount,
    output [11:0] vcount,
    output [15:0] TFT_RGB,
    output TFT_HS,
    output TFT_VS,
    output TFT_BLANK,
    output TFT_VCLK,
    output TFT_DE
);

reg [11:0] hcount_r;
reg [11:0] vcount_r;

parameter hpixel_begin = 12'd0;
parameter hpixel_end   = 12'd800;
parameter vline_begin = 12'd0;
parameter vline_end    = 12'd480;

parameter hdat_begin = 12'd48;
parameter hdat_end   = 12'd752;
parameter vdat_begin = 12'd33;
parameter vdat_end   = 12'd513;

wire hcount_ov, vcount_ov;

always @(posedge Clk33M or negedge Rst_n) begin
    if (~Rst_n) begin
        hcount_r <= hpixel_begin;
        vcount_r <= vline_begin;
    end
    else begin
        if (hcount_ov) begin
            hcount_r <= hpixel_begin;
            if (vcount_ov) begin
                vcount_r <= vline_begin;
            end
            else begin
                vcount_r <= vcount_r + 1'b1;
            end
        end
        else begin
            hcount_r <= hcount_r + 1'b1;
        end
    end
end

assign hcount_ov = (hcount_r == (hpixel_end - 1'b1));
assign vcount_ov = (vcount_r == (vline_end - 1'b1));

assign hcount = hcount_r;
assign vcount = vcount_r;

assign TFT_HS = (hcount_r >= 12'd0) & (hcount_r < 12'd96);
assign TFT_VS = (vcount_r >= 12'd0) & (vcount_r < 12'd2);

assign TFT_DE = (hcount_r >= hdat_begin) & (hcount_r < hdat_end) & (vcount_r >= vdat_begin) & (vcount_r < vdat_end);
assign TFT_BLANK = TFT_DE;

assign TFT_VCLK = Clk33M;

assign TFT_RGB = TFT_DE ? data_in : 16'b0;

endmodule

module control(
input wire clk,
input wire rst,
input wire en,
input wire done_m,
output reg done,
output reg [1:0] en_mul
);
parameter [1:0]
  idle = 0,
  load = 1,
  multiply = 2,
  deploy = 3;
reg [1:0] State; reg [1:0] NextState;
  always @(State) begin
    NextState <= idle;
    done <= 1'b0;
    en_mul <= 2'b00;
    case(State)
    idle : begin
      done <= 1'b0;
      en_mul <= 2'b00;
      if((en == 1'b1)) begin
        NextState <= load;
      end
      else begin
        NextState <= idle;
      end
    end
    load : begin
      NextState <= multiply;
      done <= 1'b0;
      en_mul <= 2'b01;
    end
    multiply : begin
      done <= 1'b0;
      en_mul <= 2'b11;
      if((done_m == 1'b1)) begin
        NextState <= deploy;
      end
      else begin
        NextState <= multiply;
      end
    end
    deploy : begin
      done <= 1'b1;
      en_mul <= 2'b11;
      NextState <= idle;
    end
    endcase
  end
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b0) begin
      State <= idle;
    end else begin
      State <= NextState;
    end
  end
endmodule

module combined_system(
    input wire clk,
    input wire reset,
    input wire shift_en,
    input wire load,
    input wire serial_in,
    input wire [3:0] parallel_in,
    output wire serial_out,
    output wire [3:0] final_output
);

    wire [3:0] shift_reg_out;
