    );

    // 2's complement module
    twos_complement_4bit twos_comp (
        .in(shift_reg_out),
        .out(twos_complement_out)
    );

    // Bitwise AND operation
    assign final_output = shift_reg_out & twos_complement_out;

endmodule

module shift_register_4bit(
    input wire clk,
