module FindMaxMin (
    input [31:0] R_temp,
    input [31:0] G_temp,
    input [31:0] B_temp,
    output reg [31:0] Cmax,
    output reg [31:0] Cmin
);

always @(*) begin
    // Initialize Cmax and Cmin with R_temp
    Cmax = R_temp;
    Cmin = R_temp;

    // Compare G_temp with current Cmax and update if necessary
    if (G_temp > Cmax) begin
        Cmax = G_temp;
    end

    // Compare B_temp with current Cmax and update if necessary
    if (B_temp > Cmax) begin
        Cmax = B_temp;
    end

    // Compare G_temp with current Cmin and update if necessary
    if (G_temp < Cmin) begin
        Cmin = G_temp;
    end

    // Compare B_temp with current Cmin and update if necessary
    if (B_temp < Cmin) begin
        Cmin = B_temp;
    end
end

endmodule

