input wire reset,
input wire shift,
input wire [REG_WIDTH - 1:0] data_in,
output wire [REG_WIDTH - 1:0] data_out_parallel,
output wire data_out_serial
);
parameter [31:0] REG_WIDTH=8;
reg [REG_WIDTH - 1:0] shift_register_mem_out;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b0) begin
      shift_register_mem_out <= {((REG_WIDTH - 1)-(0)+1){1'b0}};
    end else begin
      if(shift == 1'b1) begin
        shift_register_mem_out <= {shift_register_mem_out[REG_WIDTH - 2:0],1'b0};
      end
      else begin
        shift_register_mem_out <= data_in | shift_register_mem_out;
      end
    end
  end
  assign data_out_parallel = shift_register_mem_out;
  assign data_out_serial = shift_register_mem_out[REG_WIDTH - 2];
endmodule

module EPROC_OUT2_direct(
input wire bitCLK,
input wire bitCLKx2,
input wire bitCLKx4,
input wire rst,
output wire getDataTrig,
input wire [9:0] edataIN,
input wire edataINrdy,
output wire [1:0] EdataOUT
);
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
parameter zeros2bit = 1'b0;
reg [7:0] byte_r;
reg [1:0] request_cycle_cnt = 1'b0; reg [1:0] send_count = 1'b0;
reg send_out_trig = 1'b0;
wire inp_request_trig; wire inp_request_trig_out;
  //-----------------------------------------------------------------------------------------
  // input handshaking, request cycle 4 CLKs
  //-----------------------------------------------------------------------------------------
  always @(posedge bitCLK) begin
    if(rst == 1'b1) begin
      request_cycle_cnt <= {2{1'b0}};
    end
    else begin
      if(inp_request_trig == 1'b1) begin
        request_cycle_cnt <= {2{1'b0}};
      end
      else begin
        request_cycle_cnt <= request_cycle_cnt + 1;
      end
    end
  end
  //
  assign inp_request_trig = (request_cycle_cnt == 2'b11) ? 1'b1 : 1'b0;
  //
  pulse_pdxx_pwxx #(
      .pd(0),
    .pw(1))
  inp_reques1clk(
      bitCLKx4,
    inp_request_trig,
    inp_request_trig_out);
  assign getDataTrig = inp_request_trig_out;
  //
  always @(posedge bitCLK) begin
    send_out_trig <= inp_request_trig;
  end
  //
  //-----------------------------------------------------------------------------------------
  // sending out 2 bits @ bitCLK
  //-----------------------------------------------------------------------------------------
  always @(posedge bitCLK) begin
    if(send_out_trig == 1'b1) begin
      byte_r <= edataIN[7:0];
    end
  end
  //
  always @(posedge bitCLK) begin
    if(send_out_trig == 1'b1) begin
      send_count <= {2{1'b0}};
    end
    else begin
      send_count <= send_count + 1;
    end
  end
  //
  MUX4_Nbit #(
      .N(2))
  outmux(
      .data0(byte_r[1:0]),
    .data1(byte_r[3:2]),
    .data2(byte_r[5:4]),
    .data3(byte_r[7:6]),
    .sel(send_count),
    .data_out(EdataOUT));
    //
endmodule

