module Delay #(
    parameter DELAY_CLK = 2,
    parameter WIDTH = 8
) (
    input CLK,
    input RESETN,
    input [WIDTH-1:0] DIN,
    output reg [WIDTH-1:0] DOUT,
    output DELAY_READY,
    output DELAY_VALID
);

reg [WIDTH-1:0] fifo [DELAY_CLK-1:0];
reg [DELAY_CLK-1:0] delay_cnt;

always @(posedge CLK, negedge RESETN) begin
    if (~RESETN) begin
        for (int i = 0; i < DELAY_CLK-1; i++) begin
            fifo[i] <= 0;
        end
        delay_cnt <= 0;
        DOUT <= 0;
    end else begin
        if (DELAY_CLK <= 1) begin
            DOUT <= DIN;
        end else begin
            fifo[delay_cnt] <= DIN;
            DOUT <= fifo[DELAY_CLK-1];
            delay_cnt <= (delay_cnt == DELAY_CLK-1) ? 0 : delay_cnt + 1;
        end
    end
end

assign DELAY_READY = (DELAY_CLK <= 1) || (delay_cnt != DELAY_CLK-1);
assign DELAY_VALID = (DELAY_CLK <= 1) || (delay_cnt == DELAY_CLK-1);

endmodule

