module ALU(
    input [31:0] Read_data1,
    input [31:0] Read_data2,
    input [3:0] ALU_control,
    input ALUSrc,
    input [31:0] Sign_extend,
    output reg [31:0] ALU_Result,
    output reg Zero
);

always @(*) begin
    // Select the second operand
    reg [31:0] op2;
    if (ALUSrc == 1'b0) begin
        op2 = Read_data2;
    end else begin
        op2 = Sign_extend;
    end

    // Perform the ALU operation
    case (ALU_control)
        4'b0010: begin // Addition
            ALU_Result = Read_data1 + op2;
            Zero = 1'b0;
        end
        4'b1010: begin // Subtraction
            ALU_Result = Read_data1 - op2;
            Zero = 1'b0;
        end
        4'b0110: begin // Bitwise AND
            ALU_Result = Read_data1 & op2;
            Zero = 1'b0;
        end
        4'b0100: begin // Bitwise OR
            ALU_Result = Read_data1 | op2;
            Zero = 1'b0;
        end
        4'b1001: begin // Bitwise XOR
            ALU_Result = Read_data1 ^ op2;
            Zero = 1'b0;
        end
        4'b0101: begin // Bitwise NOR
            ALU_Result = ~(Read_data1 | op2);
            Zero = 1'b0;
        end
        4'b1100: begin // Bitwise NAND
            ALU_Result = ~(Read_data1 & op2);
            Zero = 1'b0;
        end
        4'b1101: begin // Pass-through
            ALU_Result = op2;
            Zero = 1'b0;
        end
        4'b0111: begin // Equal to zero
            if (op2 == 32'b0) begin
                ALU_Result = 32'b0;
                Zero = 1'b1;
            end else begin
                ALU_Result = 32'b0;
                Zero = 1'b0;
            end
        end
        4'b0001: begin // Not equal to zero
            if (op2 != 32'b0) begin
                ALU_Result = 32'b0;
                Zero = 1'b1;
            end else begin
                ALU_Result = 32'b0;
                Zero = 1'b0;
            end
        end
        default: begin
            ALU_Result = 32'b0;
            Zero = 1'b0;
        end
    endcase
end

endmodule

