module GAME_CTRL(
input wire CLK,
input wire RST,
input wire WIN,
input wire LOSE,
input wire KEY_W,
input wire KEY_S,
input wire KEY_A,
input wire KEY_D,
output reg GEN5_EN,
output reg [2:0] SCREEN_CODE,
output wire GAME_ON,
output wire [7:0] WATER
);
// clock
// reset
// vyhra
// prohra
// klavesa W
// klavesa S
// klavesa A
// klavesa D
// vygenerovani pocatecnich komponent
// game screen code
// in game or in screen
// voda co tece v nadrzi pred zacatkem hry
// Debug mode for skiping levels
parameter DEBUG = False;
parameter [3:0]
  level1_sc = 0,
  level1 = 1,
  level2_sc = 2,
  level2 = 3,
  level3_sc = 4,
  level3 = 5,
  level4_sc = 6,
  level4 = 7,
  win_sc = 8,
  lose_sc = 9;
reg [3:0] present_st;
reg [3:0] next_st;
reg [24:0] water_speed_counter;
reg [7:0] water_in_progress;
reg game_en;
reg next_part_of_water;
  // Pametova cast stavoveho automatu
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      present_st <= level1_sc;
    end else begin
      present_st <= next_st;
    end
  end
  // Rozhodovaci cast stavoveho automatu
  always @(present_st, KEY_W, KEY_S, KEY_A, KEY_D, WIN, LOSE) begin
    case(present_st)
    level1_sc : begin
      //uvodni obrazovka
      if((KEY_S == 1'b1)) begin
        next_st <= level1;
      end
      else if((KEY_A == 1'b1 && DEBUG == True)) begin
        next_st <= level2_sc;
      end
      else if((KEY_W == 1'b1 && DEBUG == True)) begin
        next_st <= level3_sc;
      end
      else if((KEY_D == 1'b1 && DEBUG == True)) begin
        next_st <= level4_sc;
      end
      else begin
        next_st <= level1_sc;
      end
    end
    level1 : begin
      //level 1
      if((WIN == 1'b1)) begin
        next_st <= level2_sc;
      end
      else if((LOSE == 1'b1)) begin
        next_st <= lose_sc;
      end
      else begin
        next_st <= level1;
      end
    end
    level2_sc : begin
      //level 2 obrazovka
      if((KEY_S == 1'b1)) begin
        next_st <= level2;
      end
      else begin
        next_st <= level2_sc;
      end
    end
    level2 : begin
      //level 2
      if((WIN == 1'b1)) begin
        next_st <= level3_sc;
      end
      else if((LOSE == 1'b1)) begin
        next_st <= lose_sc;
      end
      else begin
        next_st <= level2;
      end
    end
    level3_sc : begin
      //level 3 obrazovka
      if((KEY_S == 1'b1)) begin
        next_st <= level3;
      end
      else begin
        next_st <= level3_sc;
      end
    end
    level3 : begin
      //level 3
      if((WIN == 1'b1)) begin
        next_st <= level4_sc;
      end
      else if((LOSE == 1'b1)) begin
        next_st <= lose_sc;
      end
      else begin
        next_st <= level3;
      end
    end
    level4_sc : begin
      //level 4 obrazovka
      if((KEY_S == 1'b1)) begin
        next_st <= level4;
      end
      else begin
        next_st <= level4_sc;
      end
    end
    level4 : begin
      //level 4
      if((WIN == 1'b1)) begin
        next_st <= win_sc;
      end
      else if((LOSE == 1'b1)) begin
        next_st <= lose_sc;
      end
      else begin
        next_st <= level4;
      end
    end
    win_sc : begin
      //win
      if((KEY_S == 1'b1)) begin
        next_st <= level1_sc;
      end
      else begin
        next_st <= win_sc;
      end
    end
    lose_sc : begin
      //lose
      if((KEY_S == 1'b1)) begin
        next_st <= level1_sc;
      end
      else begin
        next_st <= lose_sc;
      end
    end
    default : begin
      next_st <= level1_sc;
    end
    endcase
  end
  // Vystupni cast stavoveho automatu
  always @(present_st) begin
    case(present_st)
    level1_sc : begin
      // start screen
      GEN5_EN <= 1'b1;
      SCREEN_CODE <= 3'b000;
      game_en <= 1'b0;
    end
    level1 : begin
      // lvl 1
      GEN5_EN <= 1'b0;
      SCREEN_CODE <= 3'b001;
      game_en <= 1'b1;
    end
    level2_sc : begin
      // lvl 2 screen
      GEN5_EN <= 1'b1;
      SCREEN_CODE <= 3'b100;
      game_en <= 1'b0;
    end
    level2 : begin
      // lvl 2
      GEN5_EN <= 1'b0;
      SCREEN_CODE <= 3'b001;
      game_en <= 1'b1;
    end
    level3_sc : begin
      // lvl 3 screen
      GEN5_EN <= 1'b1;
      SCREEN_CODE <= 3'b101;
      game_en <= 1'b0;
    end
    level3 : begin
      // lvl 3
      GEN5_EN <= 1'b0;
      SCREEN_CODE <= 3'b001;
      game_en <= 1'b1;
    end
    level4_sc : begin
      // lvl 4 screen
      GEN5_EN <= 1'b1;
      SCREEN_CODE <= 3'b110;
      game_en <= 1'b0;
    end
    level4 : begin
      // lvl 4
      GEN5_EN <= 1'b0;
      SCREEN_CODE <= 3'b001;
      game_en <= 1'b1;
    end
    win_sc : begin
      // win screen
      GEN5_EN <= 1'b0;
      SCREEN_CODE <= 3'b010;
      game_en <= 1'b0;
    end
    lose_sc : begin
      // game over screen
      GEN5_EN <= 1'b0;
      SCREEN_CODE <= 3'b011;
      game_en <= 1'b0;
    end
    default : begin
      GEN5_EN <= 1'b0;
      SCREEN_CODE <= 3'b000;
      game_en <= 1'b0;
    end
    endcase
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      water_speed_counter <= {25{1'b0}};
      next_part_of_water <= 1'b0;
    end else begin
      if((game_en == 1'b1)) begin
        if((water_speed_counter < 10000000)) begin
          // uprav, pokud chces jinou rychlost. max 1048575
          water_speed_counter <= water_speed_counter + 1;
          next_part_of_water <= 1'b0;
        end
        else begin
          water_speed_counter <= {25{1'b0}};
          next_part_of_water <= 1'b1;
        end
      end
      else begin
        water_speed_counter <= {25{1'b0}};
        next_part_of_water <= 1'b0;
      end
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      water_in_progress <= {8{1'b0}};
    end else begin
      if((game_en == 1'b1)) begin
        if((next_part_of_water == 1'b1)) begin
          if((water_in_progress < 255)) begin
            water_in_progress <= water_in_progress + 1;
          end
          else begin
            water_in_progress <= 255;
          end
        end
      end
      else begin
        water_in_progress <= {8{1'b0}};
      end
    end
  end
  assign WATER = water_in_progress;
  assign GAME_ON = game_en;
endmodule

module fifo #(
    parameter DATA_WIDTH = 8,
    parameter ADDR_WIDTH = 4,
    parameter RAM_DEPTH = 1 << ADDR_WIDTH
) (
    input wire clock,
    input wire reset,
    input wire wn,
    input wire rn,
    input wire [DATA_WIDTH-1:0] DATAIN,
    output reg [DATA_WIDTH-1:0] DATAOUT,
    output wire full,
    output wire empty
);

    reg [DATA_WIDTH-1:0] memory [0:RAM_DEPTH-1];
    reg [ADDR_WIDTH-1:0] wptr, rptr;
    reg [ADDR_WIDTH:0] count;

    assign full = &count;
    assign empty = ~|count;

    always @(posedge clock or negedge reset) begin
        if (!reset) begin
            wptr <= 0;
            rptr <= 0;
            count <= 0;
            DATAOUT <= 0;
        end else begin
            if (wn && !full) begin
                memory[wptr] <= DATAIN;
                wptr <= wptr + 1;
            end

            if (rn && !empty) begin
                rptr <= rptr + 1;
            end

            if (wn && !rn && !full)
                count <= count + 1;
            else if (!wn && rn && !empty)
                count <= count - 1;

            DATAOUT <= memory[rptr];
        end
    end

endmodule

module Syscall(
    input wire syscall_control,
    input wire sysstall,
    input wire [31:0] v0,
    input wire [31:0] a0,
    output reg stat_control,
    output reg print
);

    initial begin
        stat_control = 0;
        print = 0;
    end

    always @* begin
        if (syscall_control && !sysstall) begin
            case (v0)
                32'd1: $display("%d", $signed(a0));
                32'd4: begin
                    print = 1;
                    #1 print = 0;
                end
            endcase
        end

        if (v0 == 32'd10) begin
            $display("Program is finished running");
            stat_control = 1;
            #1 $finish;
        end
    end

endmodule

