    input wire [21:0] gtin,
    input wire trig,
    input wire [2:0] phase,
    input wire [5:0] raw,
    output reg [24:0] gtout
);

reg trig_e;
reg [21:0] gt;

// Trigger edge detection
always @(posedge extclk or posedge trig) begin
    if (trig)
        trig_e <= 1'b1;
    else
        trig_e <= 1'b0;
end

// Data latching
