module RegisterBlock (
    input wire clk,
    input wire rstn,
    input wire APB_M_0_psel,
    input wire APB_M_0_penable,
    input wire APB_M_0_pwrite,
    input wire [31:0] APB_M_0_paddr,
    input wire [31:0] APB_M_0_pwdata,
    output reg [31:0] APB_M_0_prdata,
    output reg APB_M_0_pready,
    output wire APB_M_0_pslverr,
    output reg Start,
    input wire Busy,
    output reg [31:0] DataOut,
    input wire [31:0] DataIn,
    output reg [15:0] WR,
    output reg [15:0] ClockDiv,
    output reg [15:0] NegDel
);

    reg RegStart;
    reg [31:0] RegDataOut;
    reg [15:0] RegWR;
    reg [15:0] RegClockDiv;
    reg [15:0] RegNegDel;

    wire apb_write = APB_M_0_psel && APB_M_0_penable && APB_M_0_pwrite;
    wire apb_read = APB_M_0_psel && APB_M_0_penable && !APB_M_0_pwrite;

    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            RegStart <= 1'b0;
            RegDataOut <= 32'b0;
            RegWR <= 16'b0;
            RegClockDiv <= 16'b0;
            RegNegDel <= 16'b0;
            APB_M_0_pready <= 1'b0;
        end else begin
            APB_M_0_pready <= APB_M_0_psel && !APB_M_0_penable;

            if (apb_write) begin
                case (APB_M_0_paddr[7:2])
                    6'h00: RegStart <= APB_M_0_pwdata[0];
                    6'h02: RegDataOut <= APB_M_0_pwdata;
                    6'h04: RegWR <= APB_M_0_pwdata[15:0];
                    6'h05: RegClockDiv <= APB_M_0_pwdata[15:0];
                    6'h06: RegNegDel <= APB_M_0_pwdata[15:0];
                endcase
            end

            if (apb_read) begin
                case (APB_M_0_paddr[7:2])
                    6'h00: APB_M_0_prdata <= {31'b0, Start};
                    6'h01: APB_M_0_prdata <= {31'b0, Busy};
                    6'h02: APB_M_0_prdata <= RegDataOut;
                    6'h03: APB_M_0_prdata <= DataIn;
                    6'h04: APB_M_0_prdata <= {16'b0, RegWR};
                    6'h05: APB_M_0_prdata <= {16'b0, RegClockDiv};
                    6'h06: APB_M_0_prdata <= {16'b0, RegNegDel};
                    default: APB_M_0_prdata <= 32'b0;
                endcase
            end

            if (Start && Busy) begin
                RegStart <= 1'b0;
            end
        end
    end

    always @(*) begin
        Start = RegStart;
        DataOut = RegDataOut;
        WR = RegWR;
        ClockDiv = RegClockDiv;
        NegDel = RegNegDel;
    end

    assign APB_M_0_pslverr = 1'b0;

endmodule

