module RSP(
    input CLK, RESET,
    input [3:0] key_row,
    output reg [2:0] key_col,
    output reg [2:0] key_data1,
    output reg [2:0] key_data2
);

reg [1:0] state;
reg [1:0] RANDOM;
reg [1:0] user_number;
reg [1:0] rsp_number;
reg key_stop;
reg clk1, clk2;

always @(posedge CLK or posedge RESET) begin
    if (RESET) begin
        state <= 0;
        key_col <= 0;
        key_data1 <= 0;
        key_data2 <= 0;
        RANDOM <= 0;
        user_number <= 0;
        rsp_number <= 0;
        key_stop <= 0;
        clk1 <= 0;
        clk2 <= 0;
    end
    else begin
        clk1 <= ~clk1;
        clk2 <= ~clk2;

        case (state)
            0: begin // no_scan
                key_col <= 0;
                if (!key_row[0] || !key_row[1] || !key_row[2] || !key_row[3]) begin
                    key_stop <= 1;
                    state <= 1;
                end
                else begin
                    key_stop <= 0;
                    state <= 1;
                end
            end
            1: begin // column1
                key_col <= 1;
                case (key_row)
                    4'b0001: user_number <= 0; // rock
                    4'b0010: user_number <= 1; // paper
                    4'b0100: user_number <= 2; // scissors
                    default: user_number <= 0;
                endcase
                state <= 2;
            end
            2: begin // column2
                key_col <= 2;
                state <= 3;
            end
            3: begin // column3
                key_col <= 3;
                if (key_stop) begin
                    RANDOM <= $random % 3;
                    rsp_number <= RANDOM;
                    case (user_number)
                        0: key_data1 <= 1; // rock
                        1: key_data1 <= 2; // paper
                        2: key_data1 <= 3; // scissors
                        default: key_data1 <= 0;
                    endcase
                    case (rsp_number)
                        0: key_data2 <= 1; // rock
                        1: key_data2 <= 2; // paper
                        2: key_data2 <= 3; // scissors
                        default: key_data2 <= 0;
                    endcase
                end
                state <= 0;
            end
            default: state <= 0;
        endcase
    end
end
endmodule

module timer(
input wire clk,
input wire clock_50,
input wire rst,
input wire [31:0] tin,
output wire [31:0] tout,
input wire wr,
output wire INT,
input wire IACK
);
parameter [31:0] speed=500;
//Use 50MHz for time keeping standard
reg [31:0] data_reg;
reg done;
  assign tout[0] = done;
  //-------------------------------------------------------
  //Generating internal clock according to speed parameter
  //Must run on the 50MHz clock so the time is correct
  //-------------------------------------------------------
  always @(posedge clock_50, posedge data_reg[0]) begin : P1
    reg [31:0] loopcount;
    if((data_reg[0] == 1'b0)) begin
      loopcount = 0;
      done <= 1'b0;
    end else begin
      if((loopcount == 49999999)) begin
        //50,000,000 cycles of 50MHz clock = 1 second
        done <= 1'b1;
      end
      else begin
        loopcount = loopcount + 1;
      end
    end
  end
  //----------------------------------------------
  //CPU write 32-bit unsigned to data register
  //This number will not be destroyed for
  //repeating time keeping function
  //Timer stops counting when data_reg=0
  //Write 0 to data_reg to stop timer
  //----------------------------------------------
  always @(posedge rst, posedge clk) begin
    if((rst == 1'b1)) begin
      data_reg <= 32'h00000000;
    end else begin
      if((wr == 1'b1)) begin
        data_reg <= tin;
      end
      //CPU write handle
    end
  end
  //---------------------------------------------
  // INT Handshaking signal handling;
  // When count is DONE, set INT 
  // When IACK is received, reset INT
  //---------------------------------------------
  always @(posedge rst, posedge iack, posedge done) begin
    if((rst == 1'b1 || iack == 1'b1)) begin
      int <= 1'b0;
    end else begin
      int <= 1'b1;
    end
  end
endmodule

