module Hex4Digs2SSeg(
input wire clock,
input wire [3:0] incr,
output reg [3:0] anodes,
output reg [7:0] cathodes
);
// Input clock
// Increment digits
// Anodes for display
// Cathodes for segments
reg [1:0] dsel = 2'b00;  // Display select
wire [3:0] hx0 = 4'b0000; wire [3:0] hx1 = 4'b0000; wire [3:0] hx2 = 4'b0000; wire [3:0] hx3 = 4'b0000;  // Hex digits
wire [7:0] sg0 = 8'b11111111; wire [7:0] sg1 = 8'b11111111; wire [7:0] sg2 = 8'b11111111; wire [7:0] sg3 = 8'b11111111;  // Segments
  // Get 4 Hex digits and assign their segments
  HexD2SSeg dig0(
      hx0,
    sg0);
  HexD2SSeg dig1(
      hx1,
    sg1);
  HexD2SSeg dig2(
      hx2,
    sg2);
  HexD2SSeg dig3(
      hx3,
    sg3);
  assign hx0 = incr[0] == 1'b1 ? hx0 + 1 : hx0;
  assign hx1 = incr[1] == 1'b1 ? hx1 + 1 : hx1;
  assign hx2 = incr[2] == 1'b1 ? hx2 + 1 : hx2;
  assign hx3 = incr[3] == 1'b1 ? hx3 + 1 : hx3;
  always @(posedge clock) begin : P1
  // choose output display with dsel
    case(dsel)
    2'b00 : begin
      cathodes <= sg0;
      anodes <= 4'b0111;
    end
    2'b01 : begin
      cathodes <= sg1;
      anodes <= 4'b1011;
    end
    2'b10 : begin
      cathodes <= sg2;
      anodes <= 4'b1101;
    end
    default : begin
      cathodes <= sg3;
      anodes <= 4'b1110;
    end
    endcase
    dsel <= dsel - 1;
  end
endmodule

module RegisterFile(
