module brown_out_reset #(
    parameter THRESHOLD = 3.3 // Default threshold voltage in volts
)(
    input wire clk,
    input wire rst,
    input wire [7:0] vdd, // Assuming 8-bit ADC value for VDD
    output reg sys_rst
);

    // Convert THRESHOLD to 8-bit ADC value (assuming 0-5V range)
    localparam THRESHOLD_ADC = $rtoi(THRESHOLD * 255 / 5);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sys_rst <= 1'b1;
        end else begin
            if (vdd < THRESHOLD_ADC) begin
                sys_rst <= 1'b1;
            end else begin
                sys_rst <= 1'b0;
            end
        end
    end

