module BCD_CNT(
input wire CLK,
input wire RESET,
output reg [11:0] DOUT12
);
reg [11:0] BCD_CNT_REG;
  always @(posedge CLK) begin
    DOUT12 <= BCD_CNT_REG;
  end
  always @(posedge CLK, posedge RESET) begin
    if(RESET == 1'b0) begin
      BCD_CNT_REG[3:0] <= {4{1'b0}};
    end else begin
      //低4位遇9变0
      if((BCD_CNT_REG[3:0] == 4'b1001)) begin
        BCD_CNT_REG[3:0] <= {4{1'b0}};
      end
      else begin
        BCD_CNT_REG[3:0] <= BCD_CNT_REG[3:0] + 1;
      end
    end
  end
  always @(posedge CLK, posedge RESET) begin
    if(RESET == 1'b0) begin
      BCD_CNT_REG[7:4] <= {4{1'b0}};
    end else begin
      //中间4位先判断是否有低4位的进位，有才会计数
      if((BCD_CNT_REG[3:0] == 4'b1001)) begin
        if((BCD_CNT_REG[7:4] == 4'b1001)) begin
          BCD_CNT_REG[7:4] <= {4{1'b0}};
        end
        else begin
          BCD_CNT_REG[7:4] <= BCD_CNT_REG[7:4] + 1;
        end
      end
      else begin
        BCD_CNT_REG[7:4] <= BCD_CNT_REG[7:4];
      end
    end
  end
  always @(posedge CLK, posedge RESET) begin
    if(RESET == 1'b0) begin
      BCD_CNT_REG[11:8] <= {4{1'b0}};
    end else begin
      //高4位先判断是否有来自中间4位的进位
      if((BCD_CNT_REG[7:4] == 4'b1001)) begin
        if((BCD_CNT_REG[11:8] == 4'b1001)) begin
          BCD_CNT_REG[11:8] <= {4{1'b0}};
        end
        else begin
          BCD_CNT_REG[11:8] <= BCD_CNT_REG[11:8] + 1;
        end
      end
      else begin
        BCD_CNT_REG[11:8] <= BCD_CNT_REG[11:8];
      end
    end
  end
endmodule

module ShiftReg(
input wire clk,
input wire ce,
input wire [width - 1:0] D,
output reg [width - 1:0] Q,
output wire [width - 1:0] S
);
parameter [31:0] width;
parameter [31:0] depth;
reg [width - 1:0] mem[depth:0] = 1'b0;  //	attribute syn_srlstyle of mem : signal is "no_rw_check";
//	attribute syn_srlstyle of mem : signal is "select_srl";	
//	synthesis syn_ramstyle = "no_rw_check";
  assign mem[0] = D;
  always @(posedge clk) begin
    if(ce == 1'b1) begin
      mem[depth:1] <= mem[depth - 1:0];
      Q <= mem[depth - 1];
    end
  end
  assign S = mem[depth];
endmodule

module top(
    input x,
    input y,
    input cin,
    output reg A,
    output reg cout
);

reg A1, cout1;
reg int1, int2, int3;

initial begin
    A = 0;
    cout = 0;
end

always @(posedge x) begin
`ifndef BUG
    A1 = ~y + &cin;
    cout1 = cin ? |y : ~^A;
    A <= (A1 & y & cin) | (A1 & ~y & ~cin) | (~A1 & y & ~cin) | (A & ~y & cin);
    cout <= cout1 & cin & ~|y;

    if (x & y)
        int1 = 1'b1;
    else if (~x & ~y)
        int1 = 1'b0;
    else
        int1 = 1'bx;

    if (y | cin)
        int2 = 1'b1;
    else if (~y & ~cin)
        int2 = 1'b0;
    else
        int2 = 1'bx;

    if (x ^ y ^ cin)
        int3 = 1'b1;
    else if (~(x ^ y ^ cin))
        int3 = 1'b0;
    else
        int3 = 1'bx;
`else
    A <= 1'bz;
    cout <= 1'bz;
`endif
end

endmodule

