module pattern;
    parameter PATNUM = 100;
    integer patcount;

    reg clk;
    reg rst_n;
    reg in_valid;
    reg [2:0] in_data1, in_data2;
    wire out_valid;
    wire [7:0] out_data;

    reg [7:0] golden_out;
    integer input_file, output_file;
    integer i;

    // Instantiate the DUT
    // Assuming DUT module is defined elsewhere or will be provided separately
    // For this fix, we'll create a dummy DUT module
    DUT dut(
        .clk(clk),
        .rst_n(rst_n),
        .in_valid(in_valid),
        .in_data1(in_data1),
        .in_data2(in_data2),
        .out_valid(out_valid),
        .out_data(out_data)
    );

    // Clock generation
    always #2.5 clk = ~clk;

    initial begin
        clk = 0;
        rst_n = 1;
        in_valid = 0;
        in_data1 = 0;
        in_data2 = 0;
        patcount = 0;

        input_file = $fopen("input.txt", "r");
        output_file = $fopen("output.txt", "r");

        if (input_file == 0 || output_file == 0) begin
            $display("Error opening files!");
            $finish;
        end

        // Reset sequence
        #10 rst_n = 0;
        #10 rst_n = 1;

        // Verify reset state
        check_reset();

        // Main test loop
        for (i = 0; i < PATNUM; i = i + 1) begin
            @(posedge clk);
            $fscanf(input_file, "%b %b", in_data1, in_data2);
            in_valid = 1;
            @(posedge clk);
            in_valid = 0;

            wait(out_valid);
            $fscanf(output_file, "%b", golden_out);

            if (out_data !== golden_out) begin
                $display("Error at pattern %0d", i);
                $display("Expected: %b, Got: %b", golden_out, out_data);
                $finish;
            end

            patcount <= patcount + 1;
        end

        $display("All %0d patterns passed!", PATNUM);
        $finish;
    end

    task check_reset;
        begin
            @(posedge clk);
            if (out_valid !== 1'b0 || out_data !== 8'b0) begin
                $display("Reset state error!");
                $display("out_valid = %b (expected 0)", out_valid);
                $display("out_data = %b (expected 00000000)", out_data);
                $finish;
            end
        end
    endtask

endmodule

