module hdb3_encoder (
    input wire i_rst_n,
    input wire i_clk,
    input wire [1:0] i_plug_b_code,
    output reg [1:0] o_hdb3_code
);

reg r_not_0_parity;

always @(posedge i_clk or negedge i_rst_n) begin
    if (!i_rst_n) begin
        o_hdb3_code <= 2'b00;
        r_not_0_parity <= 1'b0;
    end else begin
        case (i_plug_b_code)
            2'b01: begin // Positive pulse
                if (r_not_0_parity) begin
                    o_hdb3_code <= 2'b01;
                    r_not_0_parity <= ~r_not_0_parity;
                end else begin
                    o_hdb3_code <= 2'b10;
                    r_not_0_parity <= ~r_not_0_parity;
                end
            end
            2'b10: begin // Negative pulse
                if (r_not_0_parity) begin
                    o_hdb3_code <= 2'b10;
                end else begin
                    o_hdb3_code <= 2'b01;
                end
            end
            2'b11: begin // Violation
                if (r_not_0_parity) begin
                    o_hdb3_code <= 2'b01;
                    r_not_0_parity <= ~r_not_0_parity;
                end else begin
                    o_hdb3_code <= 2'b10;
                    r_not_0_parity <= ~r_not_0_parity;
                end
            end
            default: begin // No pulse (00)
                o_hdb3_code <= 2'b00;
            end
        endcase
    end
end

endmodule

