module show_explode (
    input logic Clk, reset,
    input [9:0] DrawX, DrawY,
    input [9:0] taily, tailx,
    input logic is_explode,
    input logic display_random,
    output logic is_explode_show,
    output logic [3:0] explode_index,
    output logic [1:0] state_out_explode,
    output logic change_mode_signal
);

    parameter [9:0] WIDTH = 50;
    parameter [9:0] LENGTH = 50;
    parameter [31:0] roof = 32'd10000000;

    logic [31:0] counter1, counter2;
    logic [9:0] current_x, current_y;
    logic [11:0] read_address;

    enum logic [1:0] {stay, show1, show2} state, next_state;

    always_ff @(posedge Clk) begin
        if (reset) begin
            state <= stay;
            counter1 <= 32'd0;
            counter2 <= 32'd0;
        end
        else begin
            state <= next_state;
            if (state == show1)
                counter1 <= counter1 + 1;
            else if (state == show2)
                counter2 <= counter2 + 1;
            else begin
                counter1 <= 32'd0;
                counter2 <= 32'd0;
            end
        end
    end

    always_comb begin
        next_state = state;
        case (state)
            stay: if (is_explode) next_state = show1;
            show1: if (counter1 >= roof) next_state = show2;
            show2: if (counter2 >= roof) next_state = stay;
        endcase
        if (display_random) next_state = stay;
    end

    always_comb begin
        is_explode_show = 1'b0;
        change_mode_signal = 1'b0;
        current_x = tailx - WIDTH/2;
        current_y = taily - LENGTH/2;

        if ((state == show1 || state == show2) &&
            DrawX >= current_x && DrawX < current_x + WIDTH &&
            DrawY >= current_y && DrawY < current_y + LENGTH) begin
            is_explode_show = 1'b1;
        end

        if (state == show2 && counter2 >= roof)
            change_mode_signal = 1'b1;

        read_address = (DrawX - current_x) + (DrawY - current_y) * WIDTH;
        if (state == show2)
            read_address = read_address + 12'd2500;
    end

    assign state_out_explode = state;

    explode_rom explode_rom_inst (
        .read_address(read_address),
        .Clk(Clk),
        .explode_index(explode_index)
    );

endmodule

