module LPDiRightVolumn #(
    parameter MAXDISPARITY = 64,
    parameter INPUTDATAWID = 513,
    parameter LPDI_WIDTH = 8,
    parameter OUTPUTDATAWID = 513
) (
    input wire clk,
    input wire en,
    input wire pixelEN,
    input wire sof_in,
    input wire eol_in,
    input wire [OUTPUTDATAWID-1:0] LPDiLeft_in,
    input wire rst_n,
    output reg sof_out,
    output reg eol_out,
    output reg [OUTPUTDATAWID-1:0] LPDiRight,
    output reg [OUTPUTDATAWID-1:0] LPDiLeft
);

    localparam LPDI_NUM = INPUTDATAWID / LPDI_WIDTH;

    reg [OUTPUTDATAWID-1:0] LPDiLeft_1dArray_shift_reg_sclkrate [MAXDISPARITY-1:0];
    wire [LPDI_WIDTH-1:0] LPDiLeftArrayShift_2dArray_wire [MAXDISPARITY-1:0][LPDI_NUM-1:0];
    wire [LPDI_WIDTH-1:0] LPDiRight_2DArray_wire [MAXDISPARITY-1:0][LPDI_NUM-1:0];

    integer i, j;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < MAXDISPARITY; i = i + 1) begin
                LPDiLeft_1dArray_shift_reg_sclkrate[i] <= {OUTPUTDATAWID{1'b0}};
            end
            sof_out <= 1'b0;
            eol_out <= 1'b0;
            LPDiRight <= {OUTPUTDATAWID{1'b0}};
            LPDiLeft <= {OUTPUTDATAWID{1'b0}};
        end else if (en && pixelEN) begin
            // Shift register operation
            for (i = MAXDISPARITY-1; i > 0; i = i - 1) begin
                LPDiLeft_1dArray_shift_reg_sclkrate[i] <= LPDiLeft_1dArray_shift_reg_sclkrate[i-1];
            end
            LPDiLeft_1dArray_shift_reg_sclkrate[0] <= LPDiLeft_in;

            // Output assignments
            sof_out <= LPDiLeft_1dArray_shift_reg_sclkrate[MAXDISPARITY-1][0];
            eol_out <= eol_in;
            LPDiLeft <= LPDiLeft_1dArray_shift_reg_sclkrate[MAXDISPARITY-1];

            // Assemble LPDiRight from diagonal elements
            for (i = 0; i < LPDI_NUM; i = i + 1) begin
                LPDiRight[i*LPDI_WIDTH +: LPDI_WIDTH] <= LPDiRight_2DArray_wire[i][i];
            end
        end
    end

    // Create 2D array from shift register
    genvar m, n;
    generate
        for (m = 0; m < MAXDISPARITY; m = m + 1) begin : gen_2d_array
            for (n = 0; n < LPDI_NUM; n = n + 1) begin : gen_lpdi
                assign LPDiLeftArrayShift_2dArray_wire[m][n] = LPDiLeft_1dArray_shift_reg_sclkrate[m][n*LPDI_WIDTH +: LPDI_WIDTH];
            end
        end
    endgenerate

    // Generate diagonal data
    genvar p, q;
    generate
        for (p = 0; p < MAXDISPARITY; p = p + 1) begin : gen_diagonal
            for (q = 0; q < LPDI_NUM; q = q + 1) begin : gen_right_lpdi
                if (p + q < LPDI_NUM) begin
                    assign LPDiRight_2DArray_wire[p][q] = LPDiLeftArrayShift_2dArray_wire[p][p+q];
                end else begin
                    assign LPDiRight_2DArray_wire[p][q] = {LPDI_WIDTH{1'b0}};
                end
            end
        end
    endgenerate

endmodule

module sub_147(
output wire [63:0] output,
input wire sign,
output wire ge,
input wire [63:0] in_a,
input wire [63:0] in_b
);
wire [65:0] carry_inA;
wire [65:0] carry_inB;
wire [65:0] carry_res;  // Signals to generate the comparison outputs
wire [2:0] msb_abr;
wire tmp_sign;
wire tmp_eq;
wire tmp_le;
wire tmp_ge;
  // To handle the CI input, the operation is '0' - CI
  // If CI is not present, the operation is '0' - '0'
  assign carry_inA = {1'b0,in_a,1'b0};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) - (carry_inB);
  // Set the outputs
  assign output = carry_res[64:1];
  // Other comparison outputs
  // Temporary signals
  assign msb_abr = {in_a[63],in_b[63],carry_res[64]};
  assign tmp_sign = sign;
  assign tmp_eq = in_a == in_b ? 1'b1 : 1'b0;
  assign tmp_le = msb_abr == 3'b000 || msb_abr == 3'b110 ? tmp_eq : msb_abr == 3'b001 ? 1'b1 : tmp_sign == 1'b0 && (msb_abr == 3'b010 || msb_abr == 3'b001 || msb_abr == 3'b111) ? 1'b1 : tmp_sign == 1'b1 && (msb_abr == 3'b100 || msb_abr == 3'b101) ? 1'b1 : 1'b0;
  assign tmp_ge = msb_abr == 3'b000 || msb_abr == 3'b110 ? 1'b1 : tmp_sign == 1'b0 && (msb_abr == 3'b100 || msb_abr == 3'b101) ? 1'b1 : tmp_sign == 1'b1 && (msb_abr == 3'b010 || msb_abr == 3'b011 || msb_abr == 3'b111) ? 1'b1 : 1'b0;
  assign ge = tmp_ge;
endmodule

module data_merge(
input wire pclk,
input wire reset,
input wire data_rdy_pcie,
output wire vsync_o,
input wire [15:0] stream1,
input wire [15:0] stream2,
input wire [15:0] stream3,
input wire [15:0] stream4,
output wire [7:0] dout_o
);
//this is generated from the SPI interface. Here we must sample this line using 50MHz clock	
wire pclk_data_rdy_pcie;  //pclk synced data_rdy_pcie signal
reg [7:0] dout; reg [7:0] dout_next;  //digital output 
reg vsync; reg vsync_next;
parameter [3:0]
  IDLE = 0,
  S1MSB = 1,
  S1LSB = 2,
  S2MSB = 3,
  S2LSB = 4,
  S3MSB = 5,
  S3LSB = 6,
  S4MSB = 7,
  S4LSB = 8,
  WAITLOW = 9;
  //state machine definition: 
reg [3:0] merge_state; reg [3:0] merge_state_next;
reg [3:0] sm_cnt; reg [3:0] sm_cnt_next;
  //signal assignment 
  assign vsync_o = vsync;
  assign dout_o = dout;
  //vsync triggers the data spliting process
  always @(posedge reset, posedge merge_state, posedge pclk) begin
    if((reset == 1'b1)) begin
      merge_state <= IDLE;
      dout <= {8{1'b0}};
      vsync <= 1'b0;
      sm_cnt <= {4{1'b0}};
    end else begin
      merge_state <= merge_state_next;
      dout <= dout_next;
      vsync <= vsync_next;
      sm_cnt <= sm_cnt_next;
    end
  end
  //next states 
  always @(reset, merge_state, data_rdy_pcie, sm_cnt, dout, stream1, stream2, stream3, stream4) begin
    case(merge_state)
    IDLE : begin
      if(data_rdy_pcie == 1'b1) begin
        merge_state_next <= S1MSB;
      end
      else begin
        merge_state_next <= IDLE;
      end
      dout_next <= dout;
      vsync_next <= 1'b0;
      sm_cnt_next <= {4{1'b0}};
    end
    S1MSB : begin
      merge_state_next <= S1LSB;
      dout_next <= stream1[15:8];
      vsync_next <= 1'b1;
      sm_cnt_next <= {4{1'b0}};
    end
    S1LSB : begin
      merge_state_next <= S2MSB;
      dout_next <= stream1[7:0];
      vsync_next <= 1'b1;
      sm_cnt_next <= {4{1'b0}};
    end
    S2MSB : begin
      merge_state_next <= S2LSB;
      dout_next <= stream2[15:8];
      vsync_next <= 1'b1;
      sm_cnt_next <= {4{1'b0}};
    end
    S2LSB : begin
      merge_state_next <= S3MSB;
      dout_next <= stream2[7:0];
      vsync_next <= 1'b1;
      sm_cnt_next <= {4{1'b0}};
    end
    S3MSB : begin
      merge_state_next <= S3LSB;
      dout_next <= stream3[15:8];
      vsync_next <= 1'b1;
      sm_cnt_next <= {4{1'b0}};
    end
    S3LSB : begin
      merge_state_next <= S4MSB;
      dout_next <= stream3[7:0];
      vsync_next <= 1'b1;
      sm_cnt_next <= {4{1'b0}};
    end
    S4MSB : begin
      merge_state_next <= S4LSB;
      dout_next <= stream4[15:8];
      vsync_next <= 1'b1;
      sm_cnt_next <= {4{1'b0}};
    end
    S4LSB : begin
      merge_state_next <= WAITLOW;
      dout_next <= stream4[7:0];
      vsync_next <= 1'b1;
      sm_cnt_next <= {4{1'b0}};
    end
    WAITLOW : begin
      if(data_rdy_pcie == 1'b0) begin
        if(sm_cnt >= 10) begin
          merge_state_next <= IDLE;
          vsync_next <= 1'b0;
          sm_cnt_next <= {4{1'b0}};
        end
        else begin
          sm_cnt_next <= sm_cnt + 1;
          vsync_next <= 1'b1;
          merge_state_next <= WAITLOW;
        end
      end
      else begin
        merge_state_next <= WAITLOW;
        vsync_next <= 1'b1;
        sm_cnt_next <= sm_cnt;
      end
      dout_next <= {8{1'b0}};
      //sm_cnt_next <= (others=>'0'); 
    end
    endcase
  end
endmodule

module One_ms_Timer(
    input Enable,
    output reg One_ms_timeout,
    input clk,
    input rst
);

reg [15:0] Interal_cnt;

always @(posedge clk or negedge rst) begin
    if(!rst) begin
        Interal_cnt <= 0;
        One_ms_timeout <= 0;
    end
    else if(Enable) begin
        if(Interal_cnt == 16'h1C4F) begin
            Interal_cnt <= 0;
            One_ms_timeout <= 1;
        end
        else begin
            Interal_cnt <= Interal_cnt + 1;
            One_ms_timeout <= 0;
        end
    end
    else begin
        One_ms_timeout <= 0;
    end
end

endmodule

module running_avg(
input wire clk,
input wire [size - 1:0] input,
output reg [size - 1:0] output
);
parameter [31:0] size=11;
reg [16 * size - 1:0] buff;
reg [size + 4 - 1:0] summed;
reg [size - 1:0] div;
  always @(posedge clk) begin
    buff[16 * size - 1:1 * size] <= buff[15 * size - 1:0 * size];
    //shift up
    buff[1 * size - 1:0] <= input;
    summed <= ({4'b0000,buff[16 * size - 1:15 * size]}) + ({4'b0000,buff[15 * size - 1:14 * size]}) + ({4'b0000,buff[14 * size - 1:13 * size]}) + ({4'b0000,buff[13 * size - 1:12 * size]}) + ({4'b0000,buff[12 * size - 1:11 * size]}) + ({4'b0000,buff[11 * size - 1:10 * size]}) + ({4'b0000,buff[10 * size - 1:9 * size]}) + ({4'b0000,buff[9 * size - 1:8 * size]}) + ({4'b0000,buff[8 * size - 1:7 * size]}) + ({4'b0000,buff[7 * size - 1:6 * size]}) + ({4'b0000,buff[6 * size - 1:5 * size]}) + ({4'b0000,buff[5 * size - 1:4 * size]}) + ({4'b0000,buff[4 * size - 1:3 * size]}) + ({4'b0000,buff[3 * size - 1:2 * size]}) + ({4'b0000,buff[2 * size - 1:1 * size]}) + ({4'b0000,buff[1 * size - 1:0]});
    div <= summed[size + 4 - 1:4];
    output <= div;
  end
endmodule

