module psram_clk(
    input  rstn,
    input  clk,
    input  sck_en,
    input  sck_pause,
    input  [3:0] sck_div,
    output sck_neg,
    output sck_pos,
    output sck
);

    reg [3:0] cnt;
    reg sck_int;

    wire [3:0] hi_div = sck_div[3:0];
    wire [3:0] lo_div = sck_div[3:0];

    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            cnt <= 4'd0;
            sck_int <= 1'b0;
        end
        else if (sck_en) begin
            if (!sck_pause) begin
                if (!sck_int && (cnt == lo_div - 1)) begin
                    sck_int <= 1'b1;
                    cnt <= 4'd0;
                end
                else if (sck_int && (cnt == hi_div - 1)) begin
                    sck_int <= 1'b0;
                    cnt <= 4'd0;
                end
                else begin
                    cnt <= cnt + 4'd1;
                end
            end
            else begin
                cnt <= 4'd0;
            end
        end
        else begin
            cnt <= 4'd0;
            sck_int <= 1'b0;
        end
    end

    assign sck_neg = sck_int;
    assign sck_pos = ~sck_int;
    assign sck = sck_int;

endmodule

