module adder_subtractor(
    input [3:0] a,
    input [3:0] b,
    input s,
    output c_out,
    output [3:0] result
);

    wire [3:0] b_xor;
    wire [3:0] carry;

    // XOR b with s to negate b when subtracting
    assign b_xor = b ^ {4{s}};

    // Instantiate full adders
    full_adder fa0 (.a(a[0]), .b(b_xor[0]), .carry_in(s),      .sum(result[0]), .carry_out(carry[0]));
    full_adder fa1 (.a(a[1]), .b(b_xor[1]), .carry_in(carry[0]), .sum(result[1]), .carry_out(carry[1]));
    full_adder fa2 (.a(a[2]), .b(b_xor[2]), .carry_in(carry[1]), .sum(result[2]), .carry_out(carry[2]));
    full_adder fa3 (.a(a[3]), .b(b_xor[3]), .carry_in(carry[2]), .sum(result[3]), .carry_out(c_out));

endmodule

module full_adder(
    input a,
    input b,
    input carry_in,
    output sum,
    output carry_out
);
    assign sum = a ^ b ^ carry_in;
    assign carry_out = (a & b) | (b & carry_in) | (a & carry_in);
endmodule

module divide_by_three #(
    parameter DATAWIDTH = 16
) (
    input clk,
    input rst_n,
    input vld_in,
    input [DATAWIDTH-1:0] data_in,
    output [DATAWIDTH-1:0] quotient,
    output [1:0] reminder,
    output vld_out
);

reg [DATAWIDTH-1:0] data_reg;
reg [DATAWIDTH-1:0] quotient_reg;
reg [1:0] reminder_reg;
reg [DATAWIDTH-1:0] cnt;
reg [1:0] current_state, next_state;

localparam IDLE = 2'b00;
localparam DIV_STATE0 = 2'b00;
localparam DIV_STATE1 = 2'b01;
localparam DIV_STATE2 = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        current_state <= IDLE;
        data_reg <= {DATAWIDTH{1'b0}};
        quotient_reg <= {DATAWIDTH{1'b0}};
        reminder_reg <= 2'b00;
        cnt <= {DATAWIDTH{1'b0}};
    end
    else begin
        current_state <= next_state;
        data_reg <= (vld_in) ? data_in : data_reg >> 1;
        quotient_reg <= (next_state == DIV_STATE0) ? {quotient_reg[DATAWIDTH-2:0], data_reg[DATAWIDTH-1]} : quotient_reg;
        reminder_reg <= next_state;
        cnt <= (next_state == IDLE) ? {DATAWIDTH{1'b0}} : (cnt == DATAWIDTH) ? {DATAWIDTH{1'b0}} : cnt + 1;
    end
end

always @(*) begin
    case (current_state)
        IDLE: next_state = (vld_in) ? DIV_STATE0 : IDLE;
        DIV_STATE0: next_state = DIV_STATE1;
        DIV_STATE1: next_state = DIV_STATE2;
        DIV_STATE2: next_state = (cnt == DATAWIDTH) ? IDLE : DIV_STATE0;
        default: next_state = IDLE;
    endcase
end

assign quotient = quotient_reg;
assign reminder = reminder_reg;
assign vld_out = (current_state == IDLE) && (cnt == DATAWIDTH);

endmodule

module multiplier_block (
    input [31:0] i_data0,
    output [31:0] o_data0
);

    wire [31:0] w1, w1024, w16, w17, w2176, w2193, w3217, w25736, w25753;

    assign w1 = i_data0;
    assign w1024 = w1 << 10;
    assign w16 = w1 << 4;
    assign w17 = w1 + w16;
    assign w2176 = w17 << 7;
    assign w2193 = w17 + w2176;
    assign w3217 = w2193 + w1024;
    assign w25736 = w3217 << 3;
    assign w25753 = w17 + w25736;

    assign o_data0 = w25753;

endmodule

