module i2c_master_bmp280 (
    input FPGA_CLK1_50,
    input [1:0] KEY,
    output reg i2c_scl,
    inout i2c_sda
);

    reg [9:0] i2c_clk_count;
    reg i2c_clk;
    reg [2:0] state;
    reg [7:0] address, data;
    reg [2:0] count;
    reg sda_out;
    reg GO;

    localparam IDLE = 3'd0, START = 3'd1, ADDRESS = 3'd2, RW = 3'd3, WACK = 3'd4, DATA = 3'd5, STOP = 3'd6, WACK2 = 3'd7;

    wire reset_n = KEY[0];

    always @(posedge FPGA_CLK1_50 or negedge reset_n) begin
        if (!reset_n) begin
            i2c_clk_count <= 10'd0;
            i2c_clk <= 1'b0;
        end else begin
            if (i2c_clk_count == 10'd499) begin
                i2c_clk_count <= 10'd0;
                i2c_clk <= ~i2c_clk;
            end else begin
                i2c_clk_count <= i2c_clk_count + 1'b1;
            end
        end
    end

    always @(posedge FPGA_CLK1_50 or negedge reset_n) begin
        if (!reset_n) begin
            GO <= 1'b0;
        end else if (KEY[1] == 1'b0) begin
            GO <= 1'b1;
        end else if (state == STOP) begin
            GO <= 1'b0;
        end
    end

    always @(posedge i2c_clk or negedge reset_n) begin
        if (!reset_n) begin
            state <= IDLE;
            i2c_scl <= 1'b1;
            sda_out <= 1'b1;
            address <= 8'hEE;
            data <= 8'hD0;
            count <= 3'd0;
        end else begin
            case (state)
                IDLE: begin
                    i2c_scl <= 1'b1;
                    sda_out <= 1'b1;
                    if (GO) state <= START;
                end
                START: begin
                    sda_out <= 1'b0;
                    state <= ADDRESS;
                end
                ADDRESS: begin
                    i2c_scl <= ~i2c_scl;
                    if (i2c_scl == 1'b0) begin
                        sda_out <= address[7-count];
                        if (count == 3'd7) begin
                            count <= 3'd0;
                            state <= RW;
                        end else begin
                            count <= count + 1'b1;
                        end
                    end
                end
                RW: begin
                    i2c_scl <= ~i2c_scl;
                    if (i2c_scl == 1'b0) begin
                        sda_out <= 1'b0;
                        state <= WACK;
                    end
                end
                WACK: begin
                    i2c_scl <= ~i2c_scl;
                    if (i2c_scl == 1'b1 && i2c_sda == 1'b0) begin
                        state <= DATA;
                    end
                end
                DATA: begin
                    i2c_scl <= ~i2c_scl;
                    if (i2c_scl == 1'b0) begin
                        sda_out <= data[7-count];
                        if (count == 3'd7) begin
                            count <= 3'd0;
                            state <= WACK2;
                        end else begin
                            count <= count + 1'b1;
                        end
                    end
                end
                WACK2: begin
                    i2c_scl <= ~i2c_scl;
                    if (i2c_scl == 1'b1 && i2c_sda == 1'b0) begin
                        state <= STOP;
                    end
                end
                STOP: begin
                    i2c_scl <= 1'b1;
                    sda_out <= 1'b0;
                    if (i2c_scl == 1'b1) begin
                        sda_out <= 1'b1;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end

    assign i2c_sda = (state == WACK || state == WACK2) ? 1'bz : sda_out;

endmodule

