module cbctdes(
input wire reset_i,
input wire clk_i,
input wire start_i,
input wire mode_i,
input wire [0:63] key1_i,
input wire [0:63] key2_i,
input wire [0:63] key3_i,
input wire [0:63] iv_i,
input wire [0:63] data_i,
input wire valid_i,
output wire ready_o,
output wire [0:63] data_o,
output wire valid_o
);
// low active async reset
// clock
// start cbc
// des-modus: 0 = encrypt, 1 = decrypt
// key input
// key input
// key input
// iv input
// data input
// input key/data valid flag
// ready to encrypt/decrypt
// data output
// output data valid flag
reg s_mode;
wire s_des_mode;
reg s_start;
reg [0:63] s_key1;
reg [0:63] s_key2;
reg [0:63] s_key3;
wire [0:63] s_tdes_key1;
wire [0:63] s_tdes_key2;
wire [0:63] s_tdes_key3;
reg [0:63] s_iv;
reg [0:63] s_datain;
reg [0:63] s_datain_d;
wire [0:63] s_des_datain;
wire s_validin;
wire [0:63] s_des_dataout;
reg [0:63] s_dataout;
wire s_validout;
reg s_ready;
wire s_readyout;
  assign s_des_datain = mode_i == 1'b0 && start_i == 1'b1 ? iv_i ^ data_i : s_mode == 1'b0 && start_i == 1'b0 ? s_dataout ^ data_i : data_i;
  assign data_o = s_mode == 1'b1 && s_start == 1'b1 ? s_iv ^ s_des_dataout : s_mode == 1'b1 && s_start == 1'b0 ? s_datain_d ^ s_des_dataout : s_des_dataout;
  assign s_tdes_key1 = start_i == 1'b1 ? key1_i : s_key1;
  assign s_tdes_key2 = start_i == 1'b1 ? key2_i : s_key2;
  assign s_tdes_key3 = start_i == 1'b1 ? key3_i : s_key3;
  assign s_des_mode = start_i == 1'b1 ? mode_i : s_mode;
  assign ready_o = s_ready;
  assign s_validin = valid_i & s_ready;
  assign valid_o = s_validout;
  always @(posedge clk_i, posedge reset_i) begin
    if((reset_i == 1'b0)) begin
      s_mode <= 1'b0;
      s_start <= 1'b0;
      s_key1 <= {64{1'b0}};
      s_key2 <= {64{1'b0}};
      s_key3 <= {64{1'b0}};
      s_iv <= {64{1'b0}};
      s_datain <= {64{1'b0}};
      s_datain_d <= {64{1'b0}};
    end else begin
      if((valid_i == 1'b1 && s_ready == 1'b1)) begin
        s_start <= start_i;
        s_datain <= data_i;
        s_datain_d <= s_datain;
      end
      if((valid_i == 1'b1 && s_ready == 1'b1 && start_i == 1'b1)) begin
        s_mode <= mode_i;
        s_key1 <= key1_i;
        s_key2 <= key2_i;
        s_key3 <= key3_i;
        s_iv <= iv_i;
      end
    end
  end
  always @(posedge clk_i, posedge reset_i) begin
    if((reset_i == 1'b0)) begin
      s_ready <= 1'b1;
      s_dataout <= {64{1'b0}};
    end else begin
      if((valid_i == 1'b1 && s_ready == 1'b1 && s_readyout == 1'b1)) begin
        s_ready <= 1'b0;
      end
      if((s_validout == 1'b1)) begin
        s_ready <= 1'b1;
        s_dataout <= s_des_dataout;
      end
    end
  end
  tdes i_tdes(
      .reset_i(reset_i),
    .clk_i(clk_i),
    .mode_i(s_des_mode),
    .key1_i(s_tdes_key1),
    .key2_i(s_tdes_key2),
    .key3_i(s_tdes_key3),
    .data_i(s_des_datain),
    .valid_i(s_validin),
    .data_o(s_des_dataout),
    .valid_o(s_validout),
    .ready_o(s_readyout));
endmodule

module add_211(
output wire [31:0] result,
input wire [31:0] in_a,
input wire [31:0] in_b
);
wire [33:0] carry_inA;
wire [33:0] carry_inB;
wire [33:0] carry_res;
  // To handle the CI input, the operation is '1' + CI
  // If CI is not present, the operation is '1' + '0'
  assign carry_inA = {1'b0,in_a,1'b1};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) + (carry_inB);
  // Set the outputs
  assign result = carry_res[32:1];
endmodule

