module input_queue_fifo(
input wire clk,
input wire reset,
input wire wr_en,
input wire [IQ_FIFO_DATA_WIDTH - 1:0] din,
input wire [VLAN_PRIO_WIDTH - 1:0] wr_priority,
input wire rd_en,
input wire [NR_IQ_FIFOS - 1:0] overflow,
output wire [NR_IQ_FIFOS * IQ_FIFO_DATA_WIDTH - 1:0] dout,
input wire rd_priority,
output wire [NR_IQ_FIFOS - 1:0] full,
output wire [NR_IQ_FIFOS - 1:0] empty
);
parameter [31:0] IQ_FIFO_DATA_WIDTH;
parameter [31:0] NR_IQ_FIFOS;
parameter [31:0] VLAN_PRIO_WIDTH;
reg [NR_IQ_FIFOS - 1:0] rd_en_sig = 1'b0;
reg [NR_IQ_FIFOS - 1:0] wr_en_sig = 1'b0;  // internal register, to be connected to a processor for more flexibility
wire [VLAN_PRIO_WIDTH - 1:0] high_priority_border_value_reg = 3'b001;
  always @(rd_en, wr_priority, overflow, wr_en, rd_priority, high_priority_border_value_reg) begin : P1
    reg [VLAN_PRIO_WIDTH - 1:0] wr_temp = 1'b0;
    reg [0:0] rd_temp = 1'b0;
    rd_temp[0] = rd_priority;
    wr_temp = wr_priority;
    for (i=0; i <= NR_IQ_FIFOS - 1; i = i + 1) begin
      // read access
      if((rd_en == 1'b1 && (rd_temp) == i) || (overflow[i] == 1'b1)) begin
        rd_en_sig[i] <= 1'b1;
      end
      else begin
        rd_en_sig[i] <= 1'b0;
      end
      // write access
      if(NR_IQ_FIFOS == 1) begin
        wr_en_sig[0] <= wr_en;
      end
      else begin
        if(i == 0) begin
          if(wr_temp >= high_priority_border_value_reg) begin
            wr_en_sig[i] <= 1'b0;
          end
          else begin
            wr_en_sig[i] <= wr_en;
          end
        end
        else begin
          if(wr_temp >= high_priority_border_value_reg) begin
            wr_en_sig[i] <= wr_en;
          end
          else begin
            wr_en_sig[i] <= 1'b0;
          end
        end
      end
    end
  end
  genvar i;
  generate for (i=0; i <= NR_IQ_FIFOS - 1; i = i + 1) begin: Xfifo
      fifo_generator_1 input_queue_fifo_ip(
          .clk(clk),
      .rst(reset),
      .wr_en(wr_en_sig[i]),
      .rd_en(rd_en_sig[i]),
      .din(din),
      .dout(dout[(i + 1) * IQ_FIFO_DATA_WIDTH - 1:i * IQ_FIFO_DATA_WIDTH]),
      .full(full[i]),
      .empty(empty[i]));
  end
  endgenerate
endmodule

module clkdiv #(
    parameter DIVFREQ = 100,
    parameter DIVBITS = 26,
    parameter CLKFREQ = 100_000_000,
    parameter DIVAMT = CLKFREQ / (2 * DIVFREQ)
) (
    input wire clk,
    input wire reset,
    output reg sclk
);

    reg [DIVBITS-1:0] q;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q <= 0;
            sclk <= 0;
        end else if (q == DIVAMT - 1) begin
            q <= 0;
            sclk <= ~sclk;
        end else begin
            q <= q + 1;
        end
    end

endmodule

