    end else begin
        if (in >= 8'd250) begin
            Pout = 8'b0;
        end else if (in >= 8'd240) begin
            Pout = 8'h3F;
        end else if (in >= 8'd230) begin
            Pout = 8'h7F;
        end else if (in >= 8'd220) begin
            Pout = 8'hBF;
        end else begin
            Pout = in;
        end
    end
end

