    input wire [63:0] dark_row_rdata, dark_col_rdata,
    output reg [11:0] dark_row_raddr, dark_col_raddr,
    output reg signed [15:0] G1_dark_10b, R1_dark_10b, B1_dark_10b, G2_dark_10b
);

