    reg signed [15:0] dark_row_G1, dark_row_R1, dark_row_B1, dark_row_G2;
    reg signed [15:0] dark_col_G1, dark_col_R1, dark_col_B1, dark_col_G2;

    always @(posedge clk) begin
        // Address generation
        dark_row_raddr <= vyNorm[15:4];
        dark_col_raddr <= vxNorm[15:4];

        // Dark frame data extraction
        dark_row_G1 <= $signed(dark_row_rdata[15:0]);
