        dark_col_G2 <= $signed(dark_col_rdata[63:48]);

        // Dark frame subtraction
        G1_dark_10b <= G1_10b - dark_row_G1 - dark_col_G1;
        R1_dark_10b <= R1_10b - dark_row_R1 - dark_col_R1;
        B1_dark_10b <= B1_10b - dark_row_B1 - dark_col_B1;
