  data_word darray[8];

  bit [3:0][7:0] data = {2'b10, 2'b10, 2'b10, 2'b10, 2'b10, 2'b10, 2'b10, 2'b10, 2'b10, 2'b10, 2'b10, 2'b10, 2'b10, 2'b10, 2'b10, 2'b10};

  wire [31:0] out = data;
  wire sign = data[3][7];
  wire [3:0] nib = data[0][3:0];
  wire [7:0] high_byte = data[3];
  logic [7:0] high_byte2;
  logic [15:0] word, word2;

  assign high_byte2 = data[3];
  assign word = data[1:0];

  bit [1:0][1:0][1:0][1:0] a = 2, b = 1, result;

  initial begin
