    $display("word2 = %h", word2);
    $display("a = %h, b = %h, result = %h", a, b, result);

    $finish;
  end
endmodule

module UART_LIMITER(
input wire CLOCK,
input wire RESET,
input wire WR_REQ,
output reg INHIBIT
);
reg [31:0] packet_time;
reg [31:0] byte_time;
reg [31:0] byte_count;
wire [31:0] last_count;
reg running;
wire inhibit_int;
reg inhibit_bt;
reg inhibit_bc;
parameter limit_ot = 4900;  // repeat rate of packets
parameter limit_bt = 2;  // all bytes within this time of eachother
parameter limit_bc = 33;  // limit of number of bytes
  // If the byte count or timing is exceeded, the
  // inhibit signal will precent further bytes from
  // being sent through the UART.
  assign inhibit_int = inhibit_bt | inhibit_bc;
  always @(posedge inhibit_int, posedge running) begin
    if(running == 1'b0) begin
      INHIBIT <= 1'b0;
    end else begin
      INHIBIT <= 1'b1;
    end
  end
  // Start tracking information on first write.
  always @(posedge RESET, posedge WR_REQ, posedge packet_time) begin
    if((RESET == 1'b1) || (packet_time > limit_ot)) begin
      running <= 1'b0;
    end else begin
      running <= 1'b1;
    end
  end
  // Time entire packet.
  // Once started, this timer will not reset until it reaches the
  // allowed re-send time.  The other parameters are tracked only
  // while this timer is running.
  always @(posedge CLOCK, posedge RESET, posedge running) begin
    if((RESET == 1'b1) || (running == 1'b0)) begin
      packet_time <= 0;
    end else begin
      packet_time <= packet_time + 1;
    end
  end
  // Time each byte.
  // Each byte must be received within a certain time in order for the
  // serial module to include them all in the same packet.
  always @(posedge RESET, posedge CLOCK, posedge running, posedge WR_REQ) begin
    if((RESET == 1'b1) || (running == 1'b0) || (WR_REQ == 1'b1)) begin
      byte_time <= 0;
      inhibit_bt <= 1'b0;
    end else begin
      byte_time <= byte_time + 1;
      if(byte_time >= limit_bt) begin
        inhibit_bt <= 1'b1;
      end
    end
  end
  // Count the number of bytes written.
  // Only a certain number of bytes can be sent in order
  // to keep packet size down.
  always @(negedge running, negedge WR_REQ) begin
    if(running == 1'b0) begin
      byte_count <= 0;
      inhibit_bc <= 1'b0;
    end else begin
      byte_count <= byte_count + 1;
      if(byte_count > limit_bc) begin
        inhibit_bc <= 1'b1;
      end
    end
  end
endmodule

