module parameterized_flip_flop #(
    parameter DATA_WIDTH = 32
) (
    input wire clk,
    input wire rst,
    input wire write1_en_i,
    input wire write2_en_i,
    input wire write3_en_i,
    input wire read1_en_i,
    input wire [DATA_WIDTH-1:0] data1_i,
    input wire [DATA_WIDTH-1:0] data2_i,
    input wire [DATA_WIDTH-1:0] data3_i,
    output wire [DATA_WIDTH-1:0] data1_o
);

    reg [DATA_WIDTH-1:0] data_tmp;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            data_tmp <= {DATA_WIDTH{1'b0}};
        end else if (write1_en_i) begin
            data_tmp <= data1_i;
        end else if (write2_en_i) begin
            data_tmp <= data2_i;
        end else if (write3_en_i) begin
            data_tmp <= data3_i;
        end
    end

    assign data1_o = read1_en_i ? data_tmp : {DATA_WIDTH{1'b0}};

endmodule

