module hypercpu_registers #(
    parameter REG_COUNT = 16,
    parameter REG_BITS = $clog2(REG_COUNT),
    parameter SP_ADDR = 4'hE,
    parameter PC_ADDR = 4'hF
)(
    input wire mclk,
    input wire reset,
    input wire [REG_BITS-1:0] read_a_addr,
    input wire [REG_BITS-1:0] read_b_addr,
    input wire [REG_BITS-1:0] write_addr,
    input wire [31:0] write_data,
    input wire write_enable,
    input wire [31:0] next_sp,
    input wire [31:0] next_pc,
    output wire [31:0] read_a_data,
    output wire [31:0] read_b_data,
    output wire [31:0] read_sp,
    output wire [31:0] read_pc
);

    reg [31:0] registers [0:REG_COUNT-1];
    integer i;

    assign read_a_data = registers[read_a_addr];
    assign read_b_data = registers[read_b_addr];
    assign read_sp = registers[SP_ADDR];
    assign read_pc = registers[PC_ADDR];

    always @(negedge mclk or negedge reset) begin
        if (!reset) begin
            for (i = 0; i < REG_COUNT; i = i + 1) begin
                registers[i] <= 32'b0;
            end
        end else begin
            if (write_enable) begin
                registers[write_addr] <= write_data;
            end
            registers[SP_ADDR] <= next_sp;
            registers[PC_ADDR] <= next_pc;
        end
    end

endmodule

module parameterizable_rom #(
    parameter DATA_WIDTH = 8,
    parameter ROM_DEPTH = 8,
    parameter BASE_ADDR = 0,
    parameter ROM_FILE = ""
) (
