    input wire [$clog2(ROM_DEPTH)-1:0] i_rom_rd_addr,
    output reg [DATA_WIDTH-1:0] o_rom_data_out
);

    reg [DATA_WIDTH-1:0] rom [0:ROM_DEPTH-1];
    wire cs;

    initial begin
        if (ROM_FILE != "") begin
            $readmemh(ROM_FILE, rom);
        end
    end

    assign cs = n_rst && (i_rom_rd_addr >= BASE_ADDR) && (i_rom_rd_addr < BASE_ADDR + ROM_DEPTH);

    always @(*) begin
        if (cs) begin
            o_rom_data_out = rom[i_rom_rd_addr - BASE_ADDR];
        end else begin
            o_rom_data_out = {DATA_WIDTH{1'b0}};
        end
    end

endmodule

