module branch_circ(
input wire branch_type,
input wire zero,
output reg branch_taken
);
// inputs
// BNEZ is branch_type = '1', BEQZ is branch_type = '0'
// from ALU, 1 when the result of an operation yields zero
// outputs
// 1 means the branch has to be taken
  always @(branch_type, zero) begin
    if(((branch_type == 1'b0 && zero == 1'b1) || (branch_type == 1'b1 && zero == 1'b0))) begin
      branch_taken <= 1'b1;
    end
    else begin
      branch_taken <= 1'b0;
    end
  end
