module uart_rx (
    input wire clk,
    input wire rst_n,
    input wire RX,
    input wire clr_rdy,
    output reg rdy,
    output reg [7:0] rx_data
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam START = 2'b01;
    localparam RXS = 2'b10;

    // Internal signals
    reg [1:0] state, nxt_state;
    reg [12:0] baud_cnt;
    reg [3:0] bit_cnt;
    reg [8:0] rx_shft_reg;
    reg RX_metastable, RX_stable, RX_previous;
    wire shift;

    // Baud rate generation
    assign shift = (baud_cnt == 13'h1458);

    // Input synchronization and edge detection
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            RX_metastable <= 1'b1;
            RX_stable <= 1'b1;
            RX_previous <= 1'b1;
        end else begin
            RX_metastable <= RX;
            RX_stable <= RX_metastable;
            RX_previous <= RX_stable;
        end
    end

    // FSM state transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= IDLE;
        else
            state <= nxt_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: nxt_state = (RX_previous & ~RX_stable) ? START : IDLE;
            START: nxt_state = RXS;
            RXS: nxt_state = (bit_cnt == 4'd9 && shift) ? IDLE : RXS;
            default: nxt_state = IDLE;
        endcase
    end

    // Baud counter
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            baud_cnt <= 13'h0;
        else if (state == IDLE || shift)
            baud_cnt <= 13'h0;
        else
            baud_cnt <= baud_cnt + 1'b1;
    end

    // Bit counter
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            bit_cnt <= 4'h0;
        else if (state == IDLE)
            bit_cnt <= 4'h0;
        else if (shift)
            bit_cnt <= bit_cnt + 1'b1;
    end

    // Shift register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            rx_shft_reg <= 9'h1FF;
        else if (shift)
            rx_shft_reg <= {RX_stable, rx_shft_reg[8:1]};
    end

    // Output data and ready signal
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_data <= 8'h00;
            rdy <= 1'b0;
        end else if (state == IDLE || clr_rdy) begin
            rdy <= 1'b0;
        end else if (bit_cnt == 4'd9 && shift) begin
            rx_data <= rx_shft_reg[7:0];
            rdy <= 1'b1;
        end
    end

endmodule

module PCPUcontroller (
    input wire myclk,
    input wire button,
    input wire reset,
    output reg sense
);

    // State encoding
    localparam STOP = 2'b00;
    localparam INC  = 2'b01;
    localparam TRAP = 2'b10;

    // State registers
    reg [1:0] state, nextstate;

    // State transition logic
    always @(*) begin
        case (state)
            STOP: nextstate = button ? INC : STOP;
            INC:  nextstate = TRAP;
            TRAP: nextstate = button ? TRAP : STOP;
            default: nextstate = STOP;
        endcase
    end

    // State update
    always @(posedge myclk or posedge reset) begin
        if (reset)
            state <= STOP;
        else
            state <= nextstate;
    end

    // Output logic
    always @(*) begin
        if (reset)
            sense = 1'b0;
        else if (state == INC)
            sense = 1'b1;
        else
            sense = 1'b0;
    end

endmodule

module ascii_to_int(
input wire [7:0] ascii_in,
output reg [7:0] int_out
);
  always @(ascii_in) begin
    if((ascii_in >= 8'h30 && ascii_in <= 8'h39)) begin
      int_out <= ascii_in - 8'h30;
    end
    else if((ascii_in >= 8'h41 && ascii_in <= 8'h46)) begin
      int_out <= ascii_in - 8'h41 + 10;
    end
    else begin
      int_out <= ascii_in;
    end
  end
endmodule

