module shiftR(
input wire [width - 1:0] A,
input wire Ci,
input wire [2:0] OP,
output reg [width - 1:0] S,
output reg Co
);
parameter [31:0] width=8;
  always @(A, OP, Ci) begin
    S[width - 2:0] <= A[width - 1:1];
    Co <= A[0];
    case(OP)
    3'b110 : begin
      //SR0
      S[width - 1] <= 1'b0;
    end
    3'b111 : begin
      //SR1
      S[width - 1] <= 1'b1;
    end
    3'b010 : begin
      //SRX
      S[width - 1] <= A[width - 1];
    end
    3'b000 : begin
      //SRA
      S[width - 1] <= Ci;
    end
    3'b100 : begin
      //RR
      S[width - 1] <= A[0];
    end
    default : begin
      S[width - 1] <= 1'b0;
    end
    endcase
  end
endmodule

module rst_deb #(
    parameter IN_FREQ_KHZ = 100000,
    parameter HOLD_TIME_US = 10
)(
    input  wire clkin,
    input  wire rst_n,
    output reg  rst_n_deb
);

localparam HOLD_CYCLES = IN_FREQ_KHZ * HOLD_TIME_US / 1000;
localparam CNT_WIDTH = $clog2(HOLD_CYCLES);

reg [CNT_WIDTH-1:0] cnt;
reg sig, sig_z1;
wire strobe;

always @(posedge clkin) begin
    sig <= rst_n;
    sig_z1 <= sig;
end

assign strobe = sig ^ sig_z1;

always @(posedge clkin) begin
    if (strobe || !sig) begin
        cnt <= 'd0;
        rst_n_deb <= 1'b0;
    end else if (cnt == HOLD_CYCLES-1) begin
        rst_n_deb <= 1'b1;
    end else begin
        cnt <= cnt + 1'b1;
    end
end

endmodule

module hasher(
    input clk,
    input [15:0] cur_time,
    input [15:0] student_id,
    output [15:0] cur_hash
);

reg [31:0] prev_hash;
reg [15:0] curhash;

initial begin
    prev_hash = 32'b0;
    curhash = 16'b0;
end

always @(posedge clk) begin
    prev_hash <= (((cur_time ^ student_id) - prev_hash) * (cur_time ^ student_id));
    curhash <= prev_hash[23:8];
end

assign cur_hash = curhash;

endmodule

module ADC_Controller (
    input start,
    input Comp,
    input Clock,
    output reg sample,
    output reg datardy,
    output reg [5:0] B
);

    parameter State0 = 3'b000, State1 = 3'b001, State2 = 3'b010, State3 = 3'b011, State4 = 3'b100;
    reg [2:0] currentState, nextState;
    reg beginCount, counterRst;

    always @(posedge Clock) begin
        if (currentState == State0) begin
            if (start && !Comp) begin
                nextState <= State1;
            end else begin
                nextState <= State0;
            end
        end else if (currentState == State1) begin
            if (B == 6'b111111) begin
                nextState <= State2;
            end else begin
                nextState <= State1;
            end
        end else if (currentState == State2) begin
            if (!start && !Comp) begin
                nextState <= State3;
            end else begin
                nextState <= State0;
            end
        end else if (currentState == State3) begin
            if (!start && Comp) begin
                nextState <= State4;
            end else begin
                nextState <= State3;
            end
        end else if (currentState == State4) begin
            if (start && !Comp) begin
                nextState <= State0;
            end else begin
                nextState <= State4;
            end
        end
    end

    always @(posedge Clock) begin
        currentState <= nextState;

        case (currentState)
            State0: begin
                sample <= 0;
                datardy <= 0;
                beginCount <= 0;
                counterRst <= 0;
            end
            State1: begin
                sample <= 1;
                datardy <= 0;
                beginCount <= 1;
                counterRst <= 0;
                if (beginCount) begin
                    B <= B + 1;
                end
            end
            State2: begin
                sample <= 0;
                datardy <= 0;
                beginCount <= 0;
                counterRst <= 1;
                if (counterRst) begin
                    B <= 0;
                end
            end
            State3: begin
                sample <= 0;
                datardy <= 0;
                beginCount <= 1;
                counterRst <= 0;
            end
            State4: begin
                sample <= 0;
                datardy <= 1;
                beginCount <= 0;
                counterRst <= 0;
            end
        endcase
    end

endmodule

